    "referenceSolution": "{\"javascript\":\"function moveZeroes(nums) {\\n  let insertPos = 0;\\n  for (let i = 0; i < nums.length; i++) {\\n    if (nums[i] !== 0) {\\n      let temp = nums[insertPos];\\n      nums[insertPos] = nums[i];\\n      nums[i] = temp;\\n      insertPos++;\\n    }\\n  }\\n  return nums;\\n}\",\"python\":\"def moveZeroes(nums: list[int]) -> list[int]:\\n    insert_pos = 0\\n    for i in range(len(nums)):\\n        if nums[i] != 0:\\n            nums[insert_pos], nums[i] = nums[i], nums[insert_pos]\\n            insert_pos += 1\\n    return nums\",\"java\":\"class Solution {\\n    public void moveZeroes(int[] nums) {\\n        int insertPos = 0;\\n        for (int i = 0; i < nums.length; i++) {\\n            if (nums[i] != 0) {\\n                int temp = nums[insertPos];\\n                nums[insertPos] = nums[i];\\n                nums[i] = temp;\\n                insertPos++;\\n            }\\n        }\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    void moveZeroes(vector<int>& nums) {\\n        int insertPos = 0;\\n        for (size_t i = 0; i < nums.size(); i++) {\\n            if (nums[i] != 0) swap(nums[insertPos++], nums[i]);\\n        }\\n    }\\n};\"}",
