    "starterCode": "{\"javascript\":\"function threeSum(nums) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def threeSum(nums: list[int]) -> list[list[int]]:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public void solve() {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    vector<vector<int>> threeSum(vector<int>& nums) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function threeSum(nums) {\\n  nums.sort((a, b) => a - b);\\n  const res = [];\\n  for (let i = 0; i < nums.length - 2; i++) {\\n    if (i > 0 && nums[i] === nums[i - 1]) continue;\\n    let l = i + 1, r = nums.length - 1;\\n    while (l < r) {\\n      const sum = nums[i] + nums[l] + nums[r];\\n      if (sum === 0) {\\n        res.push([nums[i], nums[l], nums[r]]);\\n        while (l < r && nums[l] === nums[l + 1]) l++;\\n        while (l < r && nums[r] === nums[r - 1]) r--;\\n        l++; r--;\\n      } else if (sum < 0) l++;\\n      else r--;\\n    }\\n  }\\n  return res;\\n}\",\"python\":\"def threeSum(nums: list[int]) -> list[list[int]]:\\n    nums.sort()\\n    res = []\\n    for i in range(len(nums) - 2):\\n        if i > 0 and nums[i] == nums[i - 1]: continue\\n        l, r = i + 1, len(nums) - 1\\n        while l < r:\\n            s = nums[i] + nums[l] + nums[r]\\n            if s == 0:\\n                res.append([nums[i], nums[l], nums[r]])\\n                while l < r and nums[l] == nums[l + 1]: l += 1\\n                while l < r and nums[r] == nums[r - 1]: r -= 1\\n                l += 1; r -= 1\\n            elif s < 0: l += 1\\n            else: r -= 1\\n    return res\",\"java\":\"class Solution {\\n    public java.util.List<java.util.List<Integer>> threeSum(int[] nums) {\\n        java.util.Arrays.sort(nums);\\n        java.util.List<java.util.List<Integer>> res = new java.util.ArrayList<>();\\n        for (int i = 0; i < nums.length - 2; i++) {\\n            if (i > 0 && nums[i] == nums[i - 1]) continue;\\n            int l = i + 1, r = nums.length - 1;\\n            while (l < r) {\\n                int sum = nums[i] + nums[l] + nums[r];\\n                if (sum == 0) {\\n                    res.add(java.util.Arrays.asList(nums[i], nums[l], nums[r]));\\n                    while (l < r && nums[l] == nums[l + 1]) l++;\\n                    while (l < r && nums[r] == nums[r - 1]) r--;\\n                    l++; r--;\\n                } else if (sum < 0) l++;\\n                else r--;\\n            }\\n        }\\n        return res;\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    vector<vector<int>> threeSum(vector<int>& nums) {\\n        sort(nums.begin(), nums.end());\\n        vector<vector<int>> res;\\n        for (int i = 0; i < (int)nums.size() - 2; i++) {\\n            if (i > 0 && nums[i] == nums[i - 1]) continue;\\n            int l = i + 1, r = nums.size() - 1;\\n            while (l < r) {\\n                int sum = nums[i] + nums[l] + nums[r];\\n                if (sum == 0) {\\n                    res.push_back({nums[i], nums[l], nums[r]});\\n                    while (l < r && nums[l] == nums[l + 1]) l++;\\n                    while (l < r && nums[r] == nums[r - 1]) r--;\\n                    l++; r--;\\n                } else if (sum < 0) l++;\\n                else r--;\\n            }\\n        }\\n        return res;\\n    }\\n};\"}",
