    "referenceSolution": "{\"javascript\":\"function subarraySum(nums, k) {\\n  const map = new Map([[0, 1]]);\\n  let sum = 0, count = 0;\\n  for (const n of nums) {\\n    sum += n;\\n    if (map.has(sum - k)) count += map.get(sum - k);\\n    map.set(sum, (map.get(sum) || 0) + 1);\\n  }\\n  return count;\\n}\",\"python\":\"def subarraySum(nums: list[int], k: int) -> int:\\n    counts = {0: 1}\\n    cur_sum = count = 0\\n    for n in nums:\\n        cur_sum += n\\n        if cur_sum - k in counts:\\n            count += counts[cur_sum - k]\\n        counts[cur_sum] = counts.get(cur_sum, 0) + 1\\n    return count\",\"java\":\"class Solution {\\n    public int subarraySum(int[] nums, int k) {\\n        java.util.Map<Integer, Integer> map = new java.util.HashMap<>();\\n        map.put(0, 1);\\n        int sum = 0, count = 0;\\n        for (int n : nums) {\\n            sum += n;\\n            count += map.getOrDefault(sum - k, 0);\\n            map.put(sum, map.getOrDefault(sum, 0) + 1);\\n        }\\n        return count;\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <unordered_map>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int subarraySum(vector<int>& nums, int k) {\\n        unordered_map<int, int> map;\\n        map[0] = 1;\\n        int sum = 0, count = 0;\\n        for (int n : nums) {\\n            sum += n;\\n            if (map.count(sum - k)) count += map[sum - k];\\n            map[sum]++;\\n        }\\n        return count;\\n    }\\n};\"}",
