    "referenceSolution": "{\"javascript\":\"function rotate(nums, k) {\\n  k %= nums.length;\\n  const reverse = (l, r) => {\\n    while (l < r) {\\n      [nums[l], nums[r]] = [nums[r], nums[l]];\\n      l++; r--;\\n    }\\n  };\\n  reverse(0, nums.length - 1);\\n  reverse(0, k - 1);\\n  reverse(k, nums.length - 1);\\n  return nums;\\n}\",\"python\":\"def rotate(nums: list[int], k: int) -> list[int]:\\n    n = len(nums)\\n    k %= n\\n    nums[:] = nums[-k:] + nums[:-k]\\n    return nums\",\"java\":\"class Solution {\\n    public void rotate(int[] nums, int k) {\\n        k %= nums.length;\\n        reverse(nums, 0, nums.length - 1);\\n        reverse(nums, 0, k - 1);\\n        reverse(nums, k, nums.length - 1);\\n    }\\n    private void reverse(int[] nums, int l, int r) {\\n        while (l < r) {\\n            int temp = nums[l];\\n            nums[l++] = nums[r];\\n            nums[r--] = temp;\\n        }\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    void rotate(vector<int>& nums, int k) {\\n        k %= nums.size();\\n        reverse(nums.begin(), nums.end());\\n        reverse(nums.begin(), nums.begin() + k);\\n        reverse(nums.begin() + k, nums.end());\\n    }\\n};\"}",
