    "starterCode": "{\"javascript\":\"function trap(height) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def trap(height: list[int]) -> int:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int trap(int[] height) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int trap(vector<int>& height) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function trap(height) {\\n  let l = 0, r = height.length - 1;\\n  let leftMax = 0, rightMax = 0, water = 0;\\n  while (l < r) {\\n    if (height[l] < height[r]) {\\n      if (height[l] >= leftMax) leftMax = height[l];\\n      else water += leftMax - height[l];\\n      l++;\\n    } else {\\n      if (height[r] >= rightMax) rightMax = height[r];\\n      else water += rightMax - height[r];\\n      r--;\\n    }\\n  }\\n  return water;\\n}\",\"python\":\"def trap(height: list[int]) -> int:\\n    l, r = 0, len(height) - 1\\n    left_max = right_max = water = 0\\n    while l < r:\\n        if height[l] < height[r]:\\n            if height[l] >= left_max: left_max = height[l]\\n            else: water += left_max - height[l]\\n            l += 1\\n        else:\\n            if height[r] >= right_max: right_max = height[r]\\n            else: water += right_max - height[r]\\n            r -= 1\\n    return water\",\"java\":\"class Solution {\\n    public int trap(int[] height) {\\n        int l = 0, r = height.length - 1;\\n        int leftMax = 0, rightMax = 0, water = 0;\\n        while (l < r) {\\n            if (height[l] < height[r]) {\\n                if (height[l] >= leftMax) leftMax = height[l];\\n                else water += leftMax - height[l];\\n                l++;\\n            } else {\\n                if (height[r] >= rightMax) rightMax = height[r];\\n                else water += rightMax - height[r];\\n                r--;\\n            }\\n        }\\n        return water;\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int trap(vector<int>& height) {\\n        int l = 0, r = height.size() - 1;\\n        int leftMax = 0, rightMax = 0, water = 0;\\n        while (l < r) {\\n            if (height[l] < height[r]) {\\n                if (height[l] >= leftMax) leftMax = height[l];\\n                else water += leftMax - height[l];\\n                l++;\\n            } else {\\n                if (height[r] >= rightMax) rightMax = height[r];\\n                else water += rightMax - height[r];\\n                r--;\\n            }\\n        }\\n        return water;\\n    }\\n};\"}",
