    "constraints": "[\"1 <= nums.length <= 10^5\",\"-2^31 <= nums[i] <= 2^31 - 1\"]",
    "hints": "[\"Place each number x in its correct index x-1 if 1 <= x <= n using cyclic sort.\",\"Iterate through the array; the first index i where nums[i] != i + 1 gives answer i + 1.\"]",
    "starterCode": "{\"javascript\":\"function firstMissingPositive(nums) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def firstMissingPositive(nums: list[int]) -> int:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int firstMissingPositive(int[] nums) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int firstMissingPositive(vector<int>& nums) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function firstMissingPositive(nums) {\\n  const n = nums.length;\\n  for (let i = 0; i < n; i++) {\\n    while (nums[i] > 0 && nums[i] <= n && nums[nums[i] - 1] !== nums[i]) {\\n      const target = nums[i] - 1;\\n      [nums[i], nums[target]] = [nums[target], nums[i]];\\n    }\\n  }\\n  for (let i = 0; i < n; i++) {\\n    if (nums[i] !== i + 1) return i + 1;\\n  }\\n  return n + 1;\\n}\",\"python\":\"def firstMissingPositive(nums: list[int]) -> int:\\n    n = len(nums)\\n    for i in range(n):\\n        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:\\n            target = nums[i] - 1\\n            nums[i], nums[target] = nums[target], nums[i]\\n    for i in range(n):\\n        if nums[i] != i + 1:\\n            return i + 1\\n    return n + 1\",\"java\":\"class Solution {\\n    public int firstMissingPositive(int[] nums) {\\n        int n = nums.length;\\n        for (int i = 0; i < n; i++) {\\n            while (nums[i] > 0 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {\\n                int target = nums[i] - 1;\\n                int temp = nums[i];\\n                nums[i] = nums[target];\\n                nums[target] = temp;\\n            }\\n        }\\n        for (int i = 0; i < n; i++) {\\n            if (nums[i] != i + 1) return i + 1;\\n        }\\n        return n + 1;\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int firstMissingPositive(vector<int>& nums) {\\n        int n = nums.size();\\n        for (int i = 0; i < n; i++) {\\n            while (nums[i] > 0 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {\\n                swap(nums[i], nums[nums[i] - 1]);\\n            }\\n        }\\n        for (int i = 0; i < n; i++) {\\n            if (nums[i] != i + 1) return i + 1;\\n        }\\n        return n + 1;\\n    }\\n};\"}",
