    "title": "Longest Substring Without Repeating Characters",
    "slug": "longest-substring-without-repeating-characters",
    "difficulty": "Medium",
    "category": "Sliding Window",
    "description": "Given a string s, find the length of the longest substring without repeating characters.",
    "examples": "[{\"input\":\"s = \\\"abcabcbb\\\"\",\"output\":\"3\",\"explanation\":\"The answer is \\\"abc\\\", with the length of 3.\"},{\"input\":\"s = \\\"bbbbb\\\"\",\"output\":\"1\",\"explanation\":\"The answer is \\\"b\\\", with the length of 1.\"}]",
    "constraints": "[\"0 <= s.length <= 5 * 10^4\",\"s consists of English letters, digits, symbols and spaces.\"]",
    "hints": "[\"Use sliding window with two pointers left and right.\",\"Store the last seen index of each character in a map.\"]",
    "starterCode": "{\"javascript\":\"function lengthOfLongestSubstring(s) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def lengthOfLongestSubstring(s: str) -> int:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int lengthOfLongestSubstring(String s) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int lengthOfLongestSubstring(string s) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function lengthOfLongestSubstring(s) {\\n  const map = new Map();\\n  let left = 0, maxLen = 0;\\n  for (let right = 0; right < s.length; right++) {\\n    if (map.has(s[right])) left = Math.max(left, map.get(s[right]) + 1);\\n    map.set(s[right], right);\\n    maxLen = Math.max(maxLen, right - left + 1);\\n  }\\n  return maxLen;\\n}\",\"python\":\"def lengthOfLongestSubstring(s: str) -> int:\\n    seen = {}\\n    left = max_len = 0\\n    for right, char in enumerate(s):\\n        if char in seen:\\n            left = max(left, seen[char] + 1)\\n        seen[char] = right\\n        max_len = max(max_len, right - left + 1)\\n    return max_len\",\"java\":\"class Solution {\\n    public int lengthOfLongestSubstring(String s) {\\n        java.util.Map<Character, Integer> map = new java.util.HashMap<>();\\n        int left = 0, maxLen = 0;\\n        for (int right = 0; right < s.length(); right++) {\\n            char c = s.charAt(right);\\n            if (map.containsKey(c)) left = Math.max(left, map.get(c) + 1);\\n            map.put(c, right);\\n            maxLen = Math.max(maxLen, right - left + 1);\\n        }\\n        return maxLen;\\n    }\\n}\",\"cpp\":\"#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int lengthOfLongestSubstring(string s) {\\n        unordered_map<char, int> map;\\n        int left = 0, maxLen = 0;\\n        for (int right = 0; right < (int)s.length(); right++) {\\n            if (map.count(s[right])) left = max(left, map[s[right]] + 1);\\n            map[s[right]] = right;\\n            maxLen = max(maxLen, right - left + 1);\\n        }\\n        return maxLen;\\n    }\\n};\"}",
