    "title": "Group Anagrams",
    "slug": "group-anagrams",
    "difficulty": "Medium",
    "category": "Strings",
    "description": "Given an array of strings strs, group the anagrams together. You can return the answer in any order.",
    "examples": "[{\"input\":\"strs = [\\\"eat\\\",\\\"tea\\\",\\\"tan\\\",\\\"ate\\\",\\\"nat\\\",\\\"bat\\\"]\",\"output\":\"[[\\\"bat\\\"],[\\\"nat\\\",\\\"tan\\\"],[\\\"ate\\\",\\\"eat\\\",\\\"tea\\\"]]\",\"explanation\":\"Anagrams grouped together.\"},{\"input\":\"strs = [\\\"\\\"]\",\"output\":\"[[\\\"\\\"]]\",\"explanation\":\"Empty string group.\"}]",
    "constraints": "[\"1 <= strs.length <= 10^4\",\"0 <= strs[i].length <= 100\",\"strs[i] consists of lowercase English letters.\"]",
    "hints": "[\"Sort each word or use character counts as a hash map key.\",\"Group all words sharing the identical key into lists.\"]",
    "starterCode": "{\"javascript\":\"function groupAnagrams(strs) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def groupAnagrams(strs: list[str]) -> list[list[str]]:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public void solve() {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    vector<vector<string>> groupAnagrams(vector<string>& strs) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function groupAnagrams(strs) {\\n  const map = new Map();\\n  for (const s of strs) {\\n    const key = s.split(\\\"\\\").sort().join(\\\"\\\");\\n    if (!map.has(key)) map.set(key, []);\\n    map.get(key).push(s);\\n  }\\n  return Array.from(map.values());\\n}\",\"python\":\"from collections import defaultdict\\n\\ndef groupAnagrams(strs: list[str]) -> list[list[str]]:\\n    groups = defaultdict(list)\\n    for s in strs:\\n        groups[\\\"\\\".join(sorted(s))].append(s)\\n    return list(groups.values())\",\"java\":\"class Solution {\\n    public java.util.List<java.util.List<String>> groupAnagrams(String[] strs) {\\n        java.util.Map<String, java.util.List<String>> map = new java.util.HashMap<>();\\n        for (String s : strs) {\\n            char[] ca = s.toCharArray();\\n            java.util.Arrays.sort(ca);\\n            String key = String.valueOf(ca);\\n            map.computeIfAbsent(key, k -> new java.util.ArrayList<>()).add(s);\\n        }\\n        return new java.util.ArrayList<>(map.values());\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    vector<vector<string>> groupAnagrams(vector<string>& strs) {\\n        unordered_map<string, vector<string>> map;\\n        for (const string& s : strs) {\\n            string key = s;\\n            sort(key.begin(), key.end());\\n            map[key].push_back(s);\\n        }\\n        vector<vector<string>> res;\\n        for (auto& pair : map) res.push_back(pair.second);\\n        return res;\\n    }\\n};\"}",
    "testCases": "[{\"input\":\"[\\\"eat\\\",\\\"tea\\\",\\\"tan\\\",\\\"ate\\\",\\\"nat\\\",\\\"bat\\\"]\",\"expectedOutput\":\"[[\\\"bat\\\"],[\\\"nat\\\",\\\"tan\\\"],[\\\"ate\\\",\\\"eat\\\",\\\"tea\\\"]]\"},{\"input\":\"[\\\"\\\"]\",\"expectedOutput\":\"[[\\\"\\\"]]\"},{\"input\":\"[\\\"a\\\"]\",\"expectedOutput\":\"[[\\\"a\\\"]]\"}]",
