    "description": "Given two strings s and t of lengths m and n respectively, return the minimum window substring of s such that every character in t (including duplicates) is included in the window. If there is no such substring, return the empty string \"\".",
    "examples": "[{\"input\":\"s = \\\"ADOBECODEBANC\\\", t = \\\"ABC\\\"\",\"output\":\"\\\"BANC\\\"\",\"explanation\":\"Minimum window containing A, B, and C.\"},{\"input\":\"s = \\\"a\\\", t = \\\"a\\\"\",\"output\":\"\\\"a\\\"\",\"explanation\":\"Exact single character match.\"}]",
    "constraints": "[\"m == s.length\",\"n == t.length\",\"1 <= m, n <= 10^5\",\"s and t consist of uppercase and lowercase English letters.\"]",
    "hints": "[\"Use sliding window with two frequency maps or counter.\",\"Expand right until all characters of t are matched, then shrink left to find minimal valid window.\"]",
    "starterCode": "{\"javascript\":\"function minWindow(s, t) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def minWindow(s: str, t: str) -> str:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public String minWindow(String s, String t) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    string minWindow(string s, string t) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function minWindow(s, t) {\\n  if (!s || !t) return \\\"\\\";\\n  const map = {};\\n  for (let c of t) map[c] = (map[c] || 0) + 1;\\n  let left = 0, right = 0, required = Object.keys(map).length;\\n  let formed = 0, windowCounts = {};\\n  let ans = [-1, 0, 0];\\n  while (right < s.length) {\\n    let c = s[right];\\n    windowCounts[c] = (windowCounts[c] || 0) + 1;\\n    if (map[c] && windowCounts[c] === map[c]) formed++;\\n    while (left <= right && formed === required) {\\n      c = s[left];\\n      if (ans[0] === -1 || (right - left + 1) < ans[0]) ans = [right - left + 1, left, right];\\n      windowCounts[c]--;\\n      if (map[c] && windowCounts[c] < map[c]) formed--;\\n      left++;\\n    }\\n    right++;\\n  }\\n  return ans[0] === -1 ? \\\"\\\" : s.substring(ans[1], ans[2] + 1);\\n}\",\"python\":\"from collections import Counter\\n\\ndef minWindow(s: str, t: str) -> str:\\n    if not s or not t: return \\\"\\\"\\n    target = Counter(t)\\n    required = len(target)\\n    left = right = formed = 0\\n    window = {}\\n    ans = float(\\\"inf\\\"), None, None\\n    while right < len(s):\\n        c = s[right]\\n        window[c] = window.get(c, 0) + 1\\n        if c in target and window[c] == target[c]: formed += 1\\n        while left <= right and formed == required:\\n            if right - left + 1 < ans[0]:\\n                ans = (right - left + 1, left, right)\\n            c = s[left]\\n            window[c] -= 1\\n            if c in target and window[c] < target[c]: formed -= 1\\n            left += 1\\n        right += 1\\n    return \\\"\\\" if ans[0] == float(\\\"inf\\\") else s[ans[1]:ans[2] + 1]\",\"java\":\"class Solution {\\n    public String minWindow(String s, String t) {\\n        if (s.length() == 0 || t.length() == 0) return \\\"\\\";\\n        java.util.Map<Character, Integer> dictT = new java.util.HashMap<>();\\n        for (char c : t.toCharArray()) dictT.put(c, dictT.getOrDefault(c, 0) + 1);\\n        int required = dictT.size(), formed = 0;\\n        java.util.Map<Character, Integer> window = new java.util.HashMap<>();\\n        int[] ans = {-1, 0, 0};\\n        int l = 0, r = 0;\\n        while (r < s.length()) {\\n            char c = s.charAt(r);\\n            window.put(c, window.getOrDefault(c, 0) + 1);\\n            if (dictT.containsKey(c) && window.get(c).intValue() == dictT.get(c).intValue()) formed++;\\n            while (l <= r && formed == required) {\\n                if (ans[0] == -1 || r - l + 1 < ans[0]) { ans[0] = r - l + 1; ans[1] = l; ans[2] = r; }\\n                char leftChar = s.charAt(l);\\n                window.put(leftChar, window.get(leftChar) - 1);\\n                if (dictT.containsKey(leftChar) && window.get(leftChar).intValue() < dictT.get(leftChar).intValue()) formed--;\\n                l++;\\n            }\\n            r++;\\n        }\\n        return ans[0] == -1 ? \\\"\\\" : s.substring(ans[1], ans[2] + 1);\\n    }\\n}\",\"cpp\":\"#include <string>\\n#include <unordered_map>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    string minWindow(string s, string t) {\\n        if (s.empty() || t.empty()) return \\\"\\\";\\n        unordered_map<char, int> target;\\n        for (char c : t) target[c]++;\\n        int required = target.size(), formed = 0;\\n        unordered_map<char, int> window;\\n        int minLen = 1e9, start = 0;\\n        int l = 0, r = 0;\\n        while (r < (int)s.length()) {\\n            char c = s[r];\\n            window[c]++;\\n            if (target.count(c) && window[c] == target[c]) formed++;\\n            while (l <= r && formed == required) {\\n                if (r - l + 1 < minLen) { minLen = r - l + 1; start = l; }\\n                char leftC = s[l];\\n                window[leftC]--;\\n                if (target.count(leftC) && window[leftC] < target[leftC]) formed--;\\n                l++;\\n            }\\n            r++;\\n        }\\n        return minLen == 1e9 ? \\\"\\\" : s.substr(start, minLen);\\n    }\\n};\"}",
