    "referenceSolution": "{\"javascript\":\"function isIsomorphic(s, t) {\\n  const mapS = new Map(), mapT = new Map();\\n  for (let i = 0; i < s.length; i++) {\\n    const c1 = s[i], c2 = t[i];\\n    if (mapS.has(c1) && mapS.get(c1) !== c2) return false;\\n    if (mapT.has(c2) && mapT.get(c2) !== c1) return false;\\n    mapS.set(c1, c2);\\n    mapT.set(c2, c1);\\n  }\\n  return true;\\n}\",\"python\":\"def isIsomorphic(s: str, t: str) -> bool:\\n    return len(set(s)) == len(set(t)) == len(set(zip(s, t)))\",\"java\":\"class Solution {\\n    public boolean isIsomorphic(String s, String t) {\\n        int[] m1 = new int[256], m2 = new int[256];\\n        for (int i = 0; i < s.length(); i++) {\\n            if (m1[s.charAt(i)] != m2[t.charAt(i)]) return false;\\n            m1[s.charAt(i)] = i + 1;\\n            m2[t.charAt(i)] = i + 1;\\n        }\\n        return true;\\n    }\\n}\",\"cpp\":\"#include <string>\\n#include <vector>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    bool isIsomorphic(string s, string t) {\\n        vector<int> m1(256, 0), m2(256, 0);\\n        for (size_t i = 0; i < s.length(); i++) {\\n            if (m1[(unsigned char)s[i]] != m2[(unsigned char)t[i]]) return false;\\n            m1[(unsigned char)s[i]] = i + 1;\\n            m2[(unsigned char)t[i]] = i + 1;\\n        }\\n        return true;\\n    }\\n};\"}",
