    "referenceSolution": "{\"javascript\":\"class MyHashMap {\\n  constructor() {\\n    this.size = 1000;\\n    this.buckets = Array.from({ length: this.size }, () => []);\\n  }\\n  put(key, value) {\\n    const b = this.buckets[key % this.size];\\n    const item = b.find(p => p[0] === key);\\n    if (item) item[1] = value;\\n    else b.push([key, value]);\\n  }\\n  get(key) {\\n    const b = this.buckets[key % this.size];\\n    const item = b.find(p => p[0] === key);\\n    return item ? item[1] : -1;\\n  }\\n  remove(key) {\\n    const b = this.buckets[key % this.size];\\n    const idx = b.findIndex(p => p[0] === key);\\n    if (idx !== -1) b.splice(idx, 1);\\n  }\\n}\",\"python\":\"class MyHashMap:\\n    def __init__(self):\\n        self.size = 1000\\n        self.table = [[] for _ in range(self.size)]\\n    def put(self, key: int, value: int) -> None:\\n        bucket = self.table[key % self.size]\\n        for i, (k, v) in enumerate(bucket):\\n            if k == key:\\n                bucket[i] = (key, value)\\n                return\\n        bucket.append((key, value))\\n    def get(self, key: int) -> int:\\n        bucket = self.table[key % self.size]\\n        for k, v in bucket:\\n            if k == key: return v\\n        return -1\\n    def remove(self, key: int) -> None:\\n        bucket = self.table[key % self.size]\\n        for i, (k, v) in enumerate(bucket):\\n            if k == key:\\n                del bucket[i]\\n                return\",\"java\":\"class MyHashMap {\\n    private int[] data;\\n    public MyHashMap() {\\n        data = new int[1000001];\\n        java.util.Arrays.fill(data, -1);\\n    }\\n    public void put(int key, int value) { data[key] = value; }\\n    public int get(int key) { return data[key]; }\\n    public void remove(int key) { data[key] = -1; }\\n}\",\"cpp\":\"#include <vector>\\nusing namespace std;\\n\\nclass MyHashMap {\\n    vector<int> data;\\npublic:\\n    MyHashMap() : data(1000001, -1) {}\\n    void put(int key, int value) { data[key] = value; }\\n    int get(int key) { return data[key]; }\\n    void remove(int key) { data[key] = -1; }\\n};\"}",
