    "starterCode": "{\"javascript\":\"function longestConsecutive(nums) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def longestConsecutive(nums: list[int]) -> int:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int longestConsecutive(int[] nums) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int longestConsecutive(vector<int>& nums) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function longestConsecutive(nums) {\\n  const set = new Set(nums);\\n  let maxLen = 0;\\n  for (const num of set) {\\n    if (!set.has(num - 1)) {\\n      let cur = num, len = 1;\\n      while (set.has(cur + 1)) { cur++; len++; }\\n      maxLen = Math.max(maxLen, len);\\n    }\\n  }\\n  return maxLen;\\n}\",\"python\":\"def longestConsecutive(nums: list[int]) -> int:\\n    num_set = set(nums)\\n    max_len = 0\\n    for n in num_set:\\n        if n - 1 not in num_set:\\n            cur = n\\n            cur_len = 1\\n            while cur + 1 in num_set:\\n                cur += 1\\n                cur_len += 1\\n            max_len = max(max_len, cur_len)\\n    return max_len\",\"java\":\"class Solution {\\n    public int longestConsecutive(int[] nums) {\\n        java.util.Set<Integer> set = new java.util.HashSet<>();\\n        for (int n : nums) set.add(n);\\n        int maxLen = 0;\\n        for (int n : set) {\\n            if (!set.contains(n - 1)) {\\n                int cur = n, len = 1;\\n                while (set.contains(cur + 1)) { cur++; len++; }\\n                maxLen = Math.max(maxLen, len);\\n            }\\n        }\\n        return maxLen;\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <unordered_set>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int longestConsecutive(vector<int>& nums) {\\n        unordered_set<int> s(nums.begin(), nums.end());\\n        int maxLen = 0;\\n        for (int n : s) {\\n            if (!s.count(n - 1)) {\\n                int cur = n, len = 1;\\n                while (s.count(cur + 1)) { cur++; len++; }\\n                maxLen = max(maxLen, len);\\n            }\\n        }\\n        return maxLen;\\n    }\\n};\"}",
