    "referenceSolution": "{\"javascript\":\"class RandomizedSet {\\n  constructor() {\\n    this.list = [];\\n    this.map = new Map();\\n  }\\n  insert(val) {\\n    if (this.map.has(val)) return false;\\n    this.map.set(val, this.list.length);\\n    this.list.push(val);\\n    return true;\\n  }\\n  remove(val) {\\n    if (!this.map.has(val)) return false;\\n    const idx = this.map.get(val);\\n    const lastVal = this.list[this.list.length - 1];\\n    this.list[idx] = lastVal;\\n    this.map.set(lastVal, idx);\\n    this.list.pop();\\n    this.map.delete(val);\\n    return true;\\n  }\\n  getRandom() {\\n    return this.list[Math.floor(Math.random() * this.list.length)];\\n  }\\n}\",\"python\":\"import random\\n\\nclass RandomizedSet:\\n    def __init__(self):\\n        self.nums = []\\n        self.pos = {}\\n    def insert(self, val: int) -> bool:\\n        if val in self.pos: return False\\n        self.pos[val] = len(self.nums)\\n        self.nums.append(val)\\n        return True\\n    def remove(self, val: int) -> bool:\\n        if val not in self.pos: return False\\n        idx, last = self.pos[val], self.nums[-1]\\n        self.nums[idx] = last\\n        self.pos[last] = idx\\n        self.nums.pop()\\n        del self.pos[val]\\n        return True\\n    def getRandom(self) -> int:\\n        return random.choice(self.nums)\",\"java\":\"class RandomizedSet {\\n    private java.util.ArrayList<Integer> nums = new java.util.ArrayList<>();\\n    private java.util.HashMap<Integer, Integer> map = new java.util.HashMap<>();\\n    private java.util.Random rand = new java.util.Random();\\n    public boolean insert(int val) {\\n        if (map.containsKey(val)) return false;\\n        map.put(val, nums.size());\\n        nums.add(val);\\n        return true;\\n    }\\n    public boolean remove(int val) {\\n        if (!map.containsKey(val)) return false;\\n        int idx = map.get(val);\\n        int last = nums.get(nums.size() - 1);\\n        nums.set(idx, last);\\n        map.put(last, idx);\\n        nums.remove(nums.size() - 1);\\n        map.remove(val);\\n        return true;\\n    }\\n    public int getRandom() { return nums.get(rand.nextInt(nums.size())); }\\n}\",\"cpp\":\"#include <vector>\\n#include <unordered_map>\\n#include <cstdlib>\\nusing namespace std;\\n\\nclass RandomizedSet {\\n    vector<int> nums;\\n    unordered_map<int, int> pos;\\npublic:\\n    bool insert(int val) {\\n        if (pos.count(val)) return false;\\n        pos[val] = nums.size();\\n        nums.push_back(val);\\n        return true;\\n    }\\n    bool remove(int val) {\\n        if (!pos.count(val)) return false;\\n        int idx = pos[val], last = nums.back();\\n        nums[idx] = last;\\n        pos[last] = idx;\\n        nums.pop_back();\\n        pos.erase(val);\\n        return true;\\n    }\\n    int getRandom() { return nums[rand() % nums.size()]; }\\n};\"}",
