    "referenceSolution": "{\"javascript\":\"function maxPoints(points) {\\n  if (points.length <= 2) return points.length;\\n  let maxPts = 0;\\n  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));\\n  for (let i = 0; i < points.length; i++) {\\n    const slopes = new Map();\\n    let curMax = 0;\\n    for (let j = i + 1; j < points.length; j++) {\\n      let dx = points[j][0] - points[i][0];\\n      let dy = points[j][1] - points[i][1];\\n      const g = gcd(dx, dy);\\n      dx /= g; dy /= g;\\n      const key = `${dx}/${dy}`;\\n      slopes.set(key, (slopes.get(key) || 0) + 1);\\n      curMax = Math.max(curMax, slopes.get(key));\\n    }\\n    maxPts = Math.max(maxPts, curMax + 1);\\n  }\\n  return maxPts;\\n}\",\"python\":\"import math\\nfrom collections import defaultdict\\n\\ndef maxPoints(points: list[list[int]]) -> int:\\n    if len(points) <= 2: return len(points)\\n    max_pts = 0\\n    for i in range(len(points)):\\n        slopes = defaultdict(int)\\n        cur_max = 0\\n        for j in range(i + 1, len(points)):\\n            dx = points[j][0] - points[i][0]\\n            dy = points[j][1] - points[i][1]\\n            g = math.gcd(dx, dy)\\n            slope = (dx // g, dy // g)\\n            slopes[slope] += 1\\n            cur_max = max(cur_max, slopes[slope])\\n        max_pts = max(max_pts, cur_max + 1)\\n    return max_pts\",\"java\":\"class Solution {\\n    public int maxPoints(int[][] points) {\\n        if (points.length <= 2) return points.length;\\n        int maxPts = 0;\\n        for (int i = 0; i < points.length; i++) {\\n            java.util.Map<String, Integer> map = new java.util.HashMap<>();\\n            int curMax = 0;\\n            for (int j = i + 1; j < points.length; j++) {\\n                int dx = points[j][0] - points[i][0];\\n                int dy = points[j][1] - points[i][1];\\n                int g = gcd(dx, dy);\\n                dx /= g; dy /= g;\\n                String key = dx + \\\"/\\\" + dy;\\n                map.put(key, map.getOrDefault(key, 0) + 1);\\n                curMax = Math.max(curMax, map.get(key));\\n            }\\n            maxPts = Math.max(maxPts, curMax + 1);\\n        }\\n        return maxPts;\\n    }\\n    private int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }\\n}\",\"cpp\":\"#include <vector>\\n#include <unordered_map>\\n#include <numeric>\\n#include <string>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int maxPoints(vector<vector<int>>& points) {\\n        if (points.size() <= 2) return points.size();\\n        int maxPts = 0;\\n        for (size_t i = 0; i < points.size(); i++) {\\n            unordered_map<string, int> map;\\n            int curMax = 0;\\n            for (size_t j = i + 1; j < points.size(); j++) {\\n                int dx = points[j][0] - points[i][0];\\n                int dy = points[j][1] - points[i][1];\\n                int g = std::gcd(dx, dy);\\n                dx /= g; dy /= g;\\n                string key = to_string(dx) + \\\"/\\\" + to_string(dy);\\n                curMax = max(curMax, ++map[key]);\\n            }\\n            maxPts = max(maxPts, curMax + 1);\\n        }\\n        return maxPts;\\n    }\\n};\"}",
