    "starterCode": "{\"javascript\":\"function maxArea(height) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def maxArea(height: list[int]) -> int:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int maxArea(int[] height) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int maxArea(vector<int>& height) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function maxArea(height) {\\n  let l = 0, r = height.length - 1, maxW = 0;\\n  while (l < r) {\\n    const area = Math.min(height[l], height[r]) * (r - l);\\n    maxW = Math.max(maxW, area);\\n    if (height[l] < height[r]) l++;\\n    else r--;\\n  }\\n  return maxW;\\n}\",\"python\":\"def maxArea(height: list[int]) -> int:\\n    l, r = 0, len(height) - 1\\n    max_w = 0\\n    while l < r:\\n        area = min(height[l], height[r]) * (r - l)\\n        max_w = max(max_w, area)\\n        if height[l] < height[r]: l += 1\\n        else: r -= 1\\n    return max_w\",\"java\":\"class Solution {\\n    public int maxArea(int[] height) {\\n        int l = 0, r = height.length - 1, maxW = 0;\\n        while (l < r) {\\n            int area = Math.min(height[l], height[r]) * (r - l);\\n            maxW = Math.max(maxW, area);\\n            if (height[l] < height[r]) l++;\\n            else r--;\\n        }\\n        return maxW;\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int maxArea(vector<int>& height) {\\n        int l = 0, r = height.size() - 1, maxW = 0;\\n        while (l < r) {\\n            int area = min(height[l], height[r]) * (r - l);\\n            maxW = max(maxW, area);\\n            if (height[l] < height[r]) l++;\\n            else r--;\\n        }\\n        return maxW;\\n    }\\n};\"}",
