    "difficulty": "Medium",
    "category": "Two Pointers",
    "description": "Given an array nums with n objects colored red, white, or blue (represented as 0, 1, and 2), sort them in-place so that objects of the same color are adjacent, with the colors in the order red, white, and blue (0, 1, 2).",
    "examples": "[{\"input\":\"nums = [2,0,2,1,1,0]\",\"output\":\"[0,0,1,1,2,2]\",\"explanation\":\"Sorted in-place in 0, 1, 2 order.\"},{\"input\":\"nums = [2,0,1]\",\"output\":\"[0,1,2]\",\"explanation\":\"Sorted array.\"}]",
    "constraints": "[\"n == nums.length\",\"1 <= n <= 300\",\"nums[i] is either 0, 1, or 2.\"]",
    "hints": "[\"Dutch National Flag 3-way partitioning algorithm.\",\"Maintain low, mid, high pointers. If nums[mid] == 0 swap with low; if 2 swap with high.\"]",
    "starterCode": "{\"javascript\":\"function sortColors(nums) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def sortColors(nums: list[int]) -> list[int]:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public void sortColors(int[] nums) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    void sortColors(vector<int>& nums) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function sortColors(nums) {\\n  let low = 0, mid = 0, high = nums.length - 1;\\n  while (mid <= high) {\\n    if (nums[mid] === 0) {\\n      [nums[low], nums[mid]] = [nums[mid], nums[low]];\\n      low++; mid++;\\n    } else if (nums[mid] === 1) {\\n      mid++;\\n    } else {\\n      [nums[mid], nums[high]] = [nums[high], nums[mid]];\\n      high--;\\n    }\\n  }\\n  return nums;\\n}\",\"python\":\"def sortColors(nums: list[int]) -> list[int]:\\n    low, mid, high = 0, 0, len(nums) - 1\\n    while mid <= high:\\n        if nums[mid] == 0:\\n            nums[low], nums[mid] = nums[mid], nums[low]\\n            low += 1; mid += 1\\n        elif nums[mid] == 1:\\n            mid += 1\\n        else:\\n            nums[mid], nums[high] = nums[high], nums[mid]\\n            high -= 1\\n    return nums\",\"java\":\"class Solution {\\n    public void sortColors(int[] nums) {\\n        int low = 0, mid = 0, high = nums.length - 1;\\n        while (mid <= high) {\\n            if (nums[mid] == 0) {\\n                int t = nums[low]; nums[low++] = nums[mid]; nums[mid++] = t;\\n            } else if (nums[mid] == 1) {\\n                mid++;\\n            } else {\\n                int t = nums[mid]; nums[mid] = nums[high]; nums[high--] = t;\\n            }\\n        }\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    void sortColors(vector<int>& nums) {\\n        int low = 0, mid = 0, high = nums.size() - 1;\\n        while (mid <= high) {\\n            if (nums[mid] == 0) swap(nums[low++], nums[mid++]);\\n            else if (nums[mid] == 1) mid++;\\n            else swap(nums[mid], nums[high--]);\\n        }\\n    }\\n};\"}",
