    "examples": "[{\"input\":\"heightMap = [[1,4,3,1,3,2],[3,2,1,3,2,4],[2,3,3,2,3,1]]\",\"output\":\"4\",\"explanation\":\"Total 4 units of trapped water.\"},{\"input\":\"heightMap = [[3,3,3,3,3],[3,2,2,2,3],[3,2,1,2,3],[3,2,2,2,3],[3,3,3,3,3]]\",\"output\":\"10\",\"explanation\":\"Total 10 units trapped.\"}]",
    "constraints": "[\"m == heightMap.length\",\"n == heightMap[i].length\",\"1 <= m, n <= 200\",\"0 <= heightMap[i][j] <= 2 * 10^4\"]",
    "hints": "[\"Use a min-heap priority queue initialized with all border cells.\",\"Pop the lowest boundary cell and explore all 4 neighbors, updating water = max(0, boundary - neighbor_height).\"]",
    "starterCode": "{\"javascript\":\"function trapRainWater(heightMap) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def trapRainWater(heightMap: list[list[int]]) -> int:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int trapRainWater(int[][] heightMap) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int trapRainWater(vector<vector<int>>& heightMap) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function trapRainWater(heightMap) {\\n  if (!heightMap.length || !heightMap[0].length) return 0;\\n  const m = heightMap.length, n = heightMap[0].length;\\n  const visited = Array.from({ length: m }, () => new Array(n).fill(false));\\n  const minHeap = []; // [h, r, c]\\n  for (let r = 0; r < m; r++) {\\n    for (let c = 0; c < n; c++) {\\n      if (r === 0 || r === m - 1 || c === 0 || c === n - 1) {\\n        minHeap.push([heightMap[r][c], r, c]);\\n        visited[r][c] = true;\\n      }\\n    }\\n  }\\n  minHeap.sort((a, b) => a[0] - b[0]);\\n  let water = 0, dirs = [[0,1],[0,-1],[1,0],[-1,0]];\\n  while (minHeap.length > 0) {\\n    const [h, r, c] = minHeap.shift();\\n    for (const [dr, dc] of dirs) {\\n      const nr = r + dr, nc = c + dc;\\n      if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc]) {\\n        visited[nr][nc] = true;\\n        water += Math.max(0, h - heightMap[nr][nc]);\\n        minHeap.push([Math.max(h, heightMap[nr][nc]), nr, nc]);\\n        minHeap.sort((a, b) => a[0] - b[0]);\\n      }\\n    }\\n  }\\n  return water;\\n}\",\"python\":\"import heapq\\n\\ndef trapRainWater(heightMap: list[list[int]]) -> int:\\n    if not heightMap or not heightMap[0]: return 0\\n    m, n = len(heightMap), len(heightMap[0])\\n    visited = [[False] * n for _ in range(m)]\\n    heap = []\\n    for r in range(m):\\n        for c in range(n):\\n            if r in (0, m - 1) or c in (0, n - 1):\\n                heapq.heappush(heap, (heightMap[r][c], r, c))\\n                visited[r][c] = True\\n    water = 0\\n    while heap:\\n        h, r, c = heapq.heappop(heap)\\n        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:\\n            nr, nc = r + dr, c + dc\\n            if 0 <= nr < m and 0 <= nc < n and not visited[nr][nc]:\\n                visited[nr][nc] = True\\n                water += max(0, h - heightMap[nr][nc])\\n                heapq.heappush(heap, (max(h, heightMap[nr][nc]), nr, nc))\\n    return water\",\"java\":\"class Solution {\\n    public int trapRainWater(int[][] heightMap) {\\n        if (heightMap.length == 0 || heightMap[0].length == 0) return 0;\\n        int m = heightMap.length, n = heightMap[0].length;\\n        boolean[][] visited = new boolean[m][n];\\n        java.util.PriorityQueue<int[]> pq = new java.util.PriorityQueue<>((a, b) -> a[0] - b[0]);\\n        for (int r = 0; r < m; r++) {\\n            for (int c = 0; c < n; c++) {\\n                if (r == 0 || r == m - 1 || c == 0 || c == n - 1) {\\n                    pq.offer(new int[]{heightMap[r][c], r, c});\\n                    visited[r][c] = true;\\n                }\\n            }\\n        }\\n        int water = 0;\\n        int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};\\n        while (!pq.isEmpty()) {\\n            int[] cell = pq.poll();\\n            for (int[] d : dirs) {\\n                int nr = cell[1] + d[0], nc = cell[2] + d[1];\\n                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc]) {\\n                    visited[nr][nc] = true;\\n                    water += Math.max(0, cell[0] - heightMap[nr][nc]);\\n                    pq.offer(new int[]{Math.max(cell[0], heightMap[nr][nc]), nr, nc});\\n                }\\n            }\\n        }\\n        return water;\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <queue>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int trapRainWater(vector<vector<int>>& heightMap) {\\n        if (heightMap.empty() || heightMap[0].empty()) return 0;\\n        int m = heightMap.size(), n = heightMap[0].size();\\n        vector<vector<bool>> visited(m, vector<bool>(n, false));\\n        priority_queue<vector<int>, vector<vector<int>>, greater<vector<int>>> pq;\\n        for (int r = 0; r < m; r++) {\\n            for (int c = 0; c < n; c++) {\\n                if (r == 0 || r == m - 1 || c == 0 || c == n - 1) {\\n                    pq.push({heightMap[r][c], r, c});\\n                    visited[r][c] = true;\\n                }\\n            }\\n        }\\n        int water = 0;\\n        int dirs[4][2] = {{0,1},{0,-1},{1,0},{-1,0}};\\n        while (!pq.empty()) {\\n            auto cell = pq.top(); pq.pop();\\n            for (auto& d : dirs) {\\n                int nr = cell[1] + d[0], nc = cell[2] + d[1];\\n                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc]) {\\n                    visited[nr][nc] = true;\\n                    water += max(0, cell[0] - heightMap[nr][nc]);\\n                    pq.push({max(cell[0], heightMap[nr][nc]), nr, nc});\\n                }\\n            }\\n        }\\n        return water;\\n    }\\n};\"}",
    "testCases": "[{\"input\":\"[[1,4,3,1,3,2],[3,2,1,3,2,4],[2,3,3,2,3,1]]\",\"expectedOutput\":\"4\"},{\"input\":\"[[3,3,3,3,3],[3,2,2,2,3],[3,2,1,2,3],[3,2,2,2,3],[3,3,3,3,3]]\",\"expectedOutput\":\"10\"},{\"input\":\"Edge case input\",\"expectedOutput\":\"Expected Edge\"}]",
    "relatedSkillName": "Data Structures & Algorithms (DSA)",
