    "examples": "[{\"input\":\"nums = [1,12,-5,-6,50,3], k = 4\",\"output\":\"12.75\",\"explanation\":\"Maximum average is (12 - 5 - 6 + 50) / 4 = 51 / 4 = 12.75.\"},{\"input\":\"nums = [5], k = 1\",\"output\":\"5.0\",\"explanation\":\"Average of single element.\"}]",
