    "starterCode": "{\"javascript\":\"function findMaxAverage(nums, k) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def findMaxAverage(nums: list[int], k: int) -> float:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public double findMaxAverage(int[] nums, int k) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    double findMaxAverage(vector<int>& nums, int k) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function findMaxAverage(nums, k) {\\n  let curSum = 0;\\n  for (let i = 0; i < k; i++) curSum += nums[i];\\n  let maxSum = curSum;\\n  for (let i = k; i < nums.length; i++) {\\n    curSum += nums[i] - nums[i - k];\\n    maxSum = Math.max(maxSum, curSum);\\n  }\\n  return maxSum / k;\\n}\",\"python\":\"def findMaxAverage(nums: list[int], k: int) -> float:\\n    cur_sum = sum(nums[:k])\\n    max_sum = cur_sum\\n    for i in range(k, len(nums)):\\n        cur_sum += nums[i] - nums[i - k]\\n        max_sum = max(max_sum, cur_sum)\\n    return max_sum / k\",\"java\":\"class Solution {\\n    public double findMaxAverage(int[] nums, int k) {\\n        long curSum = 0;\\n        for (int i = 0; i < k; i++) curSum += nums[i];\\n        long maxSum = curSum;\\n        for (int i = k; i < nums.length; i++) {\\n            curSum += nums[i] - nums[i - k];\\n            maxSum = Math.max(maxSum, curSum);\\n        }\\n        return (double) maxSum / k;\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <numeric>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    double findMaxAverage(vector<int>& nums, int k) {\\n        double curSum = 0;\\n        for (int i = 0; i < k; i++) curSum += nums[i];\\n        double maxSum = curSum;\\n        for (size_t i = k; i < nums.size(); i++) {\\n            curSum += nums[i] - nums[i - k];\\n            maxSum = max(maxSum, curSum);\\n        }\\n        return maxSum / k;\\n    }\\n};\"}",
