    "description": "You are given a string s and an integer k. You can choose any character of the string and change it to any other uppercase English character at most k times. Return the length of the longest substring containing the same letter you can get after performing the above operations.",
    "examples": "[{\"input\":\"s = \\\"ABAB\\\", k = 2\",\"output\":\"4\",\"explanation\":\"Replace the two \\\"A\\\"s with \\\"B\\\"s or vice versa.\"},{\"input\":\"s = \\\"AABABBA\\\", k = 1\",\"output\":\"4\",\"explanation\":\"Replace the middle \\\"A\\\" with \\\"B\\\" to get \\\"AABBBBA\\\".\"}]",
    "constraints": "[\"1 <= s.length <= 10^5\",\"s consists of only uppercase English letters.\",\"0 <= k <= s.length\"]",
    "hints": "[\"Window validity check: (window length) - (max frequency of any single character) <= k.\",\"If invalid, shift left pointer.\"]",
    "starterCode": "{\"javascript\":\"function characterReplacement(s, k) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def characterReplacement(s: str, k: int) -> int:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int characterReplacement(String s, int k) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int characterReplacement(string s, int k) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function characterReplacement(s, k) {\\n  const count = new Array(26).fill(0);\\n  let left = 0, maxCount = 0, maxLen = 0;\\n  for (let right = 0; right < s.length; right++) {\\n    maxCount = Math.max(maxCount, ++count[s.charCodeAt(right) - 65]);\\n    while ((right - left + 1) - maxCount > k) {\\n      count[s.charCodeAt(left) - 65]--;\\n      left++;\\n    }\\n    maxLen = Math.max(maxLen, right - left + 1);\\n  }\\n  return maxLen;\\n}\",\"python\":\"def characterReplacement(s: str, k: int) -> int:\\n    count = {}\\n    left = max_count = max_len = 0\\n    for right, char in enumerate(s):\\n        count[char] = count.get(char, 0) + 1\\n        max_count = max(max_count, count[char])\\n        while (right - left + 1) - max_count > k:\\n            count[s[left]] -= 1\\n            left += 1\\n        max_len = max(max_len, right - left + 1)\\n    return max_len\",\"java\":\"class Solution {\\n    public int characterReplacement(String s, int k) {\\n        int[] count = new int[26];\\n        int left = 0, maxCount = 0, maxLen = 0;\\n        for (int right = 0; right < s.length(); right++) {\\n            maxCount = Math.max(maxCount, ++count[s.charAt(right) - 'A']);\\n            while ((right - left + 1) - maxCount > k) {\\n                count[s.charAt(left++) - 'A']--;\\n            }\\n            maxLen = Math.max(maxLen, right - left + 1);\\n        }\\n        return maxLen;\\n    }\\n}\",\"cpp\":\"#include <string>\\n#include <vector>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int characterReplacement(string s, int k) {\\n        vector<int> count(26, 0);\\n        int left = 0, maxCount = 0, maxLen = 0;\\n        for (int right = 0; right < (int)s.length(); right++) {\\n            maxCount = max(maxCount, ++count[s[right] - 'A']);\\n            while ((right - left + 1) - maxCount > k) {\\n                count[s[left++] - 'A']--;\\n            }\\n            maxLen = max(maxLen, right - left + 1);\\n        }\\n        return maxLen;\\n    }\\n};\"}",
    "testCases": "[{\"input\":\"\\\"ABAB\\\", 2\",\"expectedOutput\":\"4\"},{\"input\":\"\\\"AABABBA\\\", 1\",\"expectedOutput\":\"4\"},{\"input\":\"Edge case input\",\"expectedOutput\":\"Expected Edge\"}]",
