    "description": "Given two strings s1 and s2, return true if s2 contains a permutation of s1, or false otherwise. In other words, return true if one of s1's permutations is the substring of s2.",
    "examples": "[{\"input\":\"s1 = \\\"ab\\\", s2 = \\\"eidbaooo\\\"\",\"output\":\"true\",\"explanation\":\"s2 contains one permutation of s1 (\\\"ba\\\").\"},{\"input\":\"s1 = \\\"ab\\\", s2 = \\\"eidboaoo\\\"\",\"output\":\"false\",\"explanation\":\"s2 does not contain any permutation of s1.\"}]",
    "constraints": "[\"1 <= s1.length, s2.length <= 10^4\",\"s1 and s2 consist of lowercase English letters.\"]",
    "hints": "[\"Count frequency of characters in s1.\",\"Maintain a fixed sliding window of size len(s1) across s2 and check if frequency counts match.\"]",
    "starterCode": "{\"javascript\":\"function checkInclusion(s1, s2) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def checkInclusion(s1: str, s2: str) -> bool:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public boolean checkInclusion(String s1, String s2) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    bool checkInclusion(string s1, string s2) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function checkInclusion(s1, s2) {\\n  if (s1.length > s2.length) return false;\\n  const c1 = new Array(26).fill(0), c2 = new Array(26).fill(0);\\n  for (let i = 0; i < s1.length; i++) {\\n    c1[s1.charCodeAt(i) - 97]++;\\n    c2[s2.charCodeAt(i) - 97]++;\\n  }\\n  const match = () => c1.every((v, i) => v === c2[i]);\\n  if (match()) return true;\\n  for (let i = s1.length; i < s2.length; i++) {\\n    c2[s2.charCodeAt(i) - 97]++;\\n    c2[s2.charCodeAt(i - s1.length) - 97]--;\\n    if (match()) return true;\\n  }\\n  return false;\\n}\",\"python\":\"def checkInclusion(s1: str, s2: str) -> bool:\\n    if len(s1) > len(s2): return False\\n    c1, c2 = [0] * 26, [0] * 26\\n    for i in range(len(s1)):\\n        c1[ord(s1[i]) - 97] += 1\\n        c2[ord(s2[i]) - 97] += 1\\n    if c1 == c2: return True\\n    for i in range(len(s1), len(s2)):\\n        c2[ord(s2[i]) - 97] += 1\\n        c2[ord(s2[i - len(s1)]) - 97] -= 1\\n        if c1 == c2: return True\\n    return False\",\"java\":\"class Solution {\\n    public boolean checkInclusion(String s1, String s2) {\\n        if (s1.length() > s2.length()) return false;\\n        int[] c1 = new int[26], c2 = new int[26];\\n        for (int i = 0; i < s1.length(); i++) {\\n            c1[s1.charAt(i) - 'a']++;\\n            c2[s2.charAt(i) - 'a']++;\\n        }\\n        if (java.util.Arrays.equals(c1, c2)) return true;\\n        for (int i = s1.length(); i < s2.length(); i++) {\\n            c2[s2.charAt(i) - 'a']++;\\n            c2[s2.charAt(i - s1.length()) - 'a']--;\\n            if (java.util.Arrays.equals(c1, c2)) return true;\\n        }\\n        return false;\\n    }\\n}\",\"cpp\":\"#include <string>\\n#include <vector>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    bool checkInclusion(string s1, string s2) {\\n        if (s1.length() > s2.length()) return false;\\n        vector<int> c1(26, 0), c2(26, 0);\\n        for (size_t i = 0; i < s1.length(); i++) {\\n            c1[s1[i] - 'a']++;\\n            c2[s2[i] - 'a']++;\\n        }\\n        if (c1 == c2) return true;\\n        for (size_t i = s1.length(); i < s2.length(); i++) {\\n            c2[s2[i] - 'a']++;\\n            c2[s2[i - s1.length()] - 'a']--;\\n            if (c1 == c2) return true;\\n        }\\n        return false;\\n    }\\n};\"}",
