    "hints": "[\"Binary search on the smaller array to partition both arrays into equal left and right halves.\",\"Ensure maxLeft1 <= minRight2 and maxLeft2 <= minRight1.\"]",
    "starterCode": "{\"javascript\":\"function findMedianSortedArrays(nums1, nums2) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def findMedianSortedArrays(nums1: list[int], nums2: list[int]) -> float:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public double findMedianSortedArrays(int[] nums1, int[] nums2) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    double findMedianSortedArrays(vector<int>& nums1, vector<int>& nums2) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function findMedianSortedArrays(nums1, nums2) {\\n  if (nums1.length > nums2.length) return findMedianSortedArrays(nums2, nums1);\\n  const m = nums1.length, n = nums2.length;\\n  let l = 0, r = m;\\n  while (l <= r) {\\n    const p1 = Math.floor((l + r) / 2);\\n    const p2 = Math.floor((m + n + 1) / 2) - p1;\\n    const maxL1 = p1 === 0 ? -Infinity : nums1[p1 - 1];\\n    const minR1 = p1 === m ? Infinity : nums1[p1];\\n    const maxL2 = p2 === 0 ? -Infinity : nums2[p2 - 1];\\n    const minR2 = p2 === n ? Infinity : nums2[p2];\\n    if (maxL1 <= minR2 && maxL2 <= minR1) {\\n      if ((m + n) % 2 === 1) return Math.max(maxL1, maxL2);\\n      return (Math.max(maxL1, maxL2) + Math.min(minR1, minR2)) / 2;\\n    } else if (maxL1 > minR2) r = p1 - 1;\\n    else l = p1 + 1;\\n  }\\n  return 0;\\n}\",\"python\":\"def findMedianSortedArrays(nums1: list[int], nums2: list[int]) -> float:\\n    if len(nums1) > len(nums2): return findMedianSortedArrays(nums2, nums1)\\n    m, n = len(nums1), len(nums2)\\n    l, r = 0, m\\n    while l <= r:\\n        p1 = (l + r) // 2\\n        p2 = (m + n + 1) // 2 - p1\\n        max_l1 = float(\\\"-inf\\\") if p1 == 0 else nums1[p1 - 1]\\n        min_r1 = float(\\\"inf\\\") if p1 == m else nums1[p1]\\n        max_l2 = float(\\\"-inf\\\") if p2 == 0 else nums2[p2 - 1]\\n        min_r2 = float(\\\"inf\\\") if p2 == n else nums2[p2]\\n        if max_l1 <= min_r2 and max_l2 <= min_r1:\\n            if (m + n) % 2 == 1: return float(max(max_l1, max_l2))\\n            return (max(max_l1, max_l2) + min(min_r1, min_r2)) / 2.0\\n        elif max_l1 > min_r2: r = p1 - 1\\n        else: l = p1 + 1\\n    return 0.0\",\"java\":\"class Solution {\\n    public double findMedianSortedArrays(int[] nums1, int[] nums2) {\\n        if (nums1.length > nums2.length) return findMedianSortedArrays(nums2, nums1);\\n        int m = nums1.length, n = nums2.length;\\n        int l = 0, r = m;\\n        while (l <= r) {\\n            int p1 = (l + r) / 2;\\n            int p2 = (m + n + 1) / 2 - p1;\\n            int maxL1 = p1 == 0 ? Integer.MIN_VALUE : nums1[p1 - 1];\\n            int minR1 = p1 == m ? Integer.MAX_VALUE : nums1[p1];\\n            int maxL2 = p2 == 0 ? Integer.MIN_VALUE : nums2[p2 - 1];\\n            int minR2 = p2 == n ? Integer.MAX_VALUE : nums2[p2];\\n            if (maxL1 <= minR2 && maxL2 <= minR1) {\\n                if ((m + n) % 2 == 1) return Math.max(maxL1, maxL2);\\n                return (Math.max(maxL1, maxL2) + Math.min(minR1, minR2)) / 2.0;\\n            } else if (maxL1 > minR2) r = p1 - 1;\\n            else l = p1 + 1;\\n        }\\n        return 0.0;\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    double findMedianSortedArrays(vector<int>& nums1, vector<int>& nums2) {\\n        if (nums1.size() > nums2.size()) return findMedianSortedArrays(nums2, nums1);\\n        int m = nums1.size(), n = nums2.size();\\n        int l = 0, r = m;\\n        while (l <= r) {\\n            int p1 = (l + r) / 2;\\n            int p2 = (m + n + 1) / 2 - p1;\\n            int maxL1 = p1 == 0 ? -1e9 : nums1[p1 - 1];\\n            int minR1 = p1 == m ? 1e9 : nums1[p1];\\n            int maxL2 = p2 == 0 ? -1e9 : nums2[p2 - 1];\\n            int minR2 = p2 == n ? 1e9 : nums2[p2];\\n            if (maxL1 <= minR2 && maxL2 <= minR1) {\\n                if ((m + n) % 2 == 1) return max(maxL1, maxL2);\\n                return (max(maxL1, maxL2) + min(minR1, minR2)) / 2.0;\\n            } else if (maxL1 > minR2) r = p1 - 1;\\n            else l = p1 + 1;\\n        }\\n        return 0.0;\\n    }\\n};\"}",
