    "referenceSolution": "{\"javascript\":\"function merge(nums1, m, nums2, n) {\\n  let p1 = m - 1, p2 = n - 1, p = m + n - 1;\\n  while (p2 >= 0) {\\n    if (p1 >= 0 && nums1[p1] > nums2[p2]) {\\n      nums1[p--] = nums1[p1--];\\n    } else {\\n      nums1[p--] = nums2[p2--];\\n    }\\n  }\\n  return nums1;\\n}\",\"python\":\"def merge(nums1: list[int], m: int, nums2: list[int], n: int) -> list[int]:\\n    p1, p2, p = m - 1, n - 1, m + n - 1\\n    while p2 >= 0:\\n        if p1 >= 0 and nums1[p1] > nums2[p2]:\\n            nums1[p] = nums1[p1]\\n            p1 -= 1\\n        else:\\n            nums1[p] = nums2[p2]\\n            p2 -= 1\\n        p -= 1\\n    return nums1\",\"java\":\"class Solution {\\n    public void merge(int[] nums1, int m, int[] nums2, int n) {\\n        int p1 = m - 1, p2 = n - 1, p = m + n - 1;\\n        while (p2 >= 0) {\\n            if (p1 >= 0 && nums1[p1] > nums2[p2]) nums1[p--] = nums1[p1--];\\n            else nums1[p--] = nums2[p2--];\\n        }\\n    }\\n}\",\"cpp\":\"#include <vector>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    void merge(vector<int>& nums1, int m, vector<int>& nums2, int n) {\\n        int p1 = m - 1, p2 = n - 1, p = m + n - 1;\\n        while (p2 >= 0) {\\n            if (p1 >= 0 && nums1[p1] > nums2[p2]) nums1[p--] = nums1[p1--];\\n            else nums1[p--] = nums2[p2--];\\n        }\\n    }\\n};\"}",
