    "examples": "[{\"input\":\"nums = [5,2,3,1]\",\"output\":\"[1,2,3,5]\",\"explanation\":\"Sorted in ascending order.\"},{\"input\":\"nums = [5,1,1,2,0,0]\",\"output\":\"[0,0,1,1,2,5]\",\"explanation\":\"Handles duplicate values.\"}]",
    "constraints": "[\"1 <= nums.length <= 5 * 10^4\",\"-5 * 10^4 <= nums[i] <= 5 * 10^4\"]",
    "hints": "[\"Implement Merge Sort (divide-and-conquer) or randomized 3-way Quick Sort.\",\"Divide array recursively into two halves, sort each, and merge in O(n) time.\"]",
    "starterCode": "{\"javascript\":\"function sortArray(nums) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def sortArray(nums: list[int]) -> list[int]:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int[] sortArray(int[] nums) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    vector<int> sortArray(vector<int>& nums) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function sortArray(nums) {\\n  if (nums.length <= 1) return nums;\\n  const mid = Math.floor(nums.length / 2);\\n  const left = sortArray(nums.slice(0, mid));\\n  const right = sortArray(nums.slice(mid));\\n  const res = [];\\n  let i = 0, j = 0;\\n  while (i < left.length && j < right.length) {\\n    if (left[i] <= right[j]) res.push(left[i++]);\\n    else res.push(right[j++]);\\n  }\\n  return res.concat(left.slice(i)).concat(right.slice(j));\\n}\",\"python\":\"def sortArray(nums: list[int]) -> list[int]:\\n    if len(nums) <= 1: return nums\\n    mid = len(nums) // 2\\n    left = sortArray(nums[:mid])\\n    right = sortArray(nums[mid:])\\n    res, i, j = [], 0, 0\\n    while i < len(left) and j < len(right):\\n        if left[i] <= right[j]: res.append(left[i]); i += 1\\n        else: res.append(right[j]); j += 1\\n    res.extend(left[i:]); res.extend(right[j:])\\n    return res\",\"java\":\"class Solution {\\n    public int[] sortArray(int[] nums) {\\n        mergeSort(nums, 0, nums.length - 1);\\n        return nums;\\n    }\\n    private void mergeSort(int[] a, int l, int r) {\\n        if (l >= r) return;\\n        int m = l + (r - l) / 2;\\n        mergeSort(a, l, m);\\n        mergeSort(a, m + 1, r);\\n        merge(a, l, m, r);\\n    }\\n    private void merge(int[] a, int l, int m, int r) {\\n        int[] temp = new int[r - l + 1];\\n        int i = l, j = m + 1, k = 0;\\n        while (i <= m && j <= r) temp[k++] = a[i] <= a[j] ? a[i++] : a[j++];\\n        while (i <= m) temp[k++] = a[i++];\\n        while (j <= r) temp[k++] = a[j++];\\n        System.arraycopy(temp, 0, a, l, temp.length);\\n    }\\n}\",\"cpp\":\"#include <vector>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    vector<int> sortArray(vector<int>& nums) {\\n        mergeSort(nums, 0, (int)nums.size() - 1);\\n        return nums;\\n    }\\n    void mergeSort(vector<int>& a, int l, int r) {\\n        if (l >= r) return;\\n        int m = l + (r - l) / 2;\\n        mergeSort(a, l, m); mergeSort(a, m + 1, r);\\n        vector<int> temp(r - l + 1);\\n        int i = l, j = m + 1, k = 0;\\n        while (i <= m && j <= r) temp[k++] = a[i] <= a[j] ? a[i++] : a[j++];\\n        while (i <= m) temp[k++] = a[i++];\\n        while (j <= r) temp[k++] = a[j++];\\n        for (int p = 0; p < k; p++) a[l + p] = temp[p];\\n    }\\n};\"}",
