    "title": "Kth Largest Element in an Array",
    "slug": "kth-largest-element-in-an-array",
    "difficulty": "Medium",
    "category": "Sorting",
    "description": "Given an integer array nums and an integer k, return the kth largest element in the array. Can be solved using QuickSelect in O(n) average time or a Min-Heap of size k in O(n log k) time.",
    "examples": "[{\"input\":\"nums = [3,2,1,5,6,4], k = 2\",\"output\":\"5\",\"explanation\":\"2nd largest is 5.\"},{\"input\":\"nums = [3,2,3,1,2,4,5,5,6], k = 4\",\"output\":\"4\",\"explanation\":\"4th largest is 4.\"}]",
    "constraints": "[\"1 <= k <= nums.length <= 10^5\",\"-10^4 <= nums[i] <= 10^4\"]",
    "hints": "[\"Use Quickselect partitioning around a random pivot.\",\"If pivot index equals n - k, return nums[pivot].\"]",
    "starterCode": "{\"javascript\":\"function findKthLargest(nums, k) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def findKthLargest(nums: list[int], k: int) -> int:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int findKthLargest(int[] nums, int k) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int findKthLargest(vector<int>& nums, int k) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function findKthLargest(nums, k) {\\n  const targetIdx = nums.length - k;\\n  function quickSelect(l, r) {\\n    const pivot = nums[r];\\n    let p = l;\\n    for (let i = l; i < r; i++) {\\n      if (nums[i] <= pivot) {\\n        [nums[p], nums[i]] = [nums[i], nums[p]];\\n        p++;\\n      }\\n    }\\n    [nums[p], nums[r]] = [nums[r], nums[p]];\\n    if (p === targetIdx) return nums[p];\\n    if (p < targetIdx) return quickSelect(p + 1, r);\\n    return quickSelect(l, p - 1);\\n  }\\n  return quickSelect(0, nums.length - 1);\\n}\",\"python\":\"import heapq\\n\\ndef findKthLargest(nums: list[int], k: int) -> int:\\n    return heapq.nlargest(k, nums)[-1]\",\"java\":\"class Solution {\\n    public int findKthLargest(int[] nums, int k) {\\n        java.util.PriorityQueue<Integer> pq = new java.util.PriorityQueue<>();\\n        for (int n : nums) {\\n            pq.offer(n);\\n            if (pq.size() > k) pq.poll();\\n        }\\n        return pq.peek();\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <queue>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int findKthLargest(vector<int>& nums, int k) {\\n        priority_queue<int, vector<int>, greater<int>> pq;\\n        for (int n : nums) {\\n            pq.push(n);\\n            if ((int)pq.size() > k) pq.pop();\\n        }\\n        return pq.top();\\n    }\\n};\"}",
