    "starterCode": "{\"javascript\":\"function mergeTwoLists(list1, list2) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def mergeTwoLists(list1, list2):\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public ListNode mergeTwoLists(ListNode list1, ListNode list2) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    ListNode* mergeTwoLists(ListNode* list1, ListNode* list2) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function mergeTwoLists(list1, list2) {\\n  const dummy = { val: 0, next: null };\\n  let tail = dummy;\\n  while (list1 && list2) {\\n    if (list1.val <= list2.val) {\\n      tail.next = list1;\\n      list1 = list1.next;\\n    } else {\\n      tail.next = list2;\\n      list2 = list2.next;\\n    }\\n    tail = tail.next;\\n  }\\n  tail.next = list1 || list2;\\n  return dummy.next;\\n}\",\"python\":\"def mergeTwoLists(list1, list2):\\n    dummy = ListNode(0)\\n    tail = dummy\\n    while list1 and list2:\\n        if list1.val <= list2.val:\\n            tail.next = list1\\n            list1 = list1.next\\n        else:\\n            tail.next = list2\\n            list2 = list2.next\\n        tail = tail.next\\n    tail.next = list1 or list2\\n    return dummy.next\",\"java\":\"class Solution {\\n    public ListNode mergeTwoLists(ListNode list1, ListNode list2) {\\n        ListNode dummy = new ListNode(0);\\n        ListNode tail = dummy;\\n        while (list1 != null && list2 != null) {\\n            if (list1.val <= list2.val) {\\n                tail.next = list1; list1 = list1.next;\\n            } else {\\n                tail.next = list2; list2 = list2.next;\\n            }\\n            tail = tail.next;\\n        }\\n        tail.next = list1 != null ? list1 : list2;\\n        return dummy.next;\\n    }\\n}\",\"cpp\":\"class Solution {\\npublic:\\n    ListNode* mergeTwoLists(ListNode* list1, ListNode* list2) {\\n        ListNode dummy(0);\\n        ListNode* tail = &dummy;\\n        while (list1 && list2) {\\n            if (list1->val <= list2->val) {\\n                tail->next = list1; list1 = list1->next;\\n            } else {\\n                tail->next = list2; list2 = list2->next;\\n            }\\n            tail = tail->next;\\n        }\\n        tail->next = list1 ? list1 : list2;\\n        return dummy.next;\\n    }\\n};\"}",
