    "referenceSolution": "{\"javascript\":\"function hasCycle(head) {\\n  let slow = head, fast = head;\\n  while (fast && fast.next) {\\n    slow = slow.next;\\n    fast = fast.next.next;\\n    if (slow === fast) return true;\\n  }\\n  return false;\\n}\",\"python\":\"def hasCycle(head) -> bool:\\n    slow = fast = head\\n    while fast and fast.next:\\n        slow = slow.next\\n        fast = fast.next.next\\n        if slow == fast: return True\\n    return False\",\"java\":\"public class Solution {\\n    public boolean hasCycle(ListNode head) {\\n        ListNode slow = head, fast = head;\\n        while (fast != null && fast.next != null) {\\n            slow = slow.next;\\n            fast = fast.next.next;\\n            if (slow == fast) return true;\\n        }\\n        return false;\\n    }\\n}\",\"cpp\":\"class Solution {\\npublic:\\n    bool hasCycle(ListNode *head) {\\n        ListNode *slow = head, *fast = head;\\n        while (fast && fast->next) {\\n            slow = slow->next;\\n            fast = fast->next->next;\\n            if (slow == fast) return true;\\n        }\\n        return false;\\n    }\\n};\"}",
