    "description": "You are given two non-empty linked lists representing two non-negative integers. The digits are stored in reverse order, and each of their nodes contains a single digit. Add the two numbers and return the sum as a linked list.",
    "examples": "[{\"input\":\"l1 = [2,4,3], l2 = [5,6,4]\",\"output\":\"[7,0,8]\",\"explanation\":\"342 + 465 = 807.\"},{\"input\":\"l1 = [0], l2 = [0]\",\"output\":\"[0]\",\"explanation\":\"0 + 0 = 0.\"}]",
    "constraints": "[\"The number of nodes in each linked list is in the range [1, 100].\",\"0 <= Node.val <= 9\",\"It is guaranteed that the list represents a number that does not have leading zeros.\"]",
    "hints": "[\"Maintain carry = Math.floor(sum / 10).\",\"Iterate while l1, l2, or carry exists, creating new nodes with sum % 10.\"]",
    "starterCode": "{\"javascript\":\"function addTwoNumbers(l1, l2) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def addTwoNumbers(l1, l2):\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function addTwoNumbers(l1, l2) {\\n  const dummy = { val: 0, next: null };\\n  let curr = dummy, carry = 0;\\n  while (l1 || l2 || carry) {\\n    const sum = (l1 ? l1.val : 0) + (l2 ? l2.val : 0) + carry;\\n    carry = Math.floor(sum / 10);\\n    curr.next = { val: sum % 10, next: null };\\n    curr = curr.next;\\n    if (l1) l1 = l1.next;\\n    if (l2) l2 = l2.next;\\n  }\\n  return dummy.next;\\n}\",\"python\":\"def addTwoNumbers(l1, l2):\\n    dummy = ListNode(0)\\n    curr = dummy\\n    carry = 0\\n    while l1 or l2 or carry:\\n        s = (l1.val if l1 else 0) + (l2.val if l2 else 0) + carry\\n        carry = s // 10\\n        curr.next = ListNode(s % 10)\\n        curr = curr.next\\n        l1 = l1.next if l1 else None\\n        l2 = l2.next if l2 else None\\n    return dummy.next\",\"java\":\"class Solution {\\n    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {\\n        ListNode dummy = new ListNode(0);\\n        ListNode curr = dummy;\\n        int carry = 0;\\n        while (l1 != null || l2 != null || carry != 0) {\\n            int sum = (l1 != null ? l1.val : 0) + (l2 != null ? l2.val : 0) + carry;\\n            carry = sum / 10;\\n            curr.next = new ListNode(sum % 10);\\n            curr = curr.next;\\n            if (l1 != null) l1 = l1.next;\\n            if (l2 != null) l2 = l2.next;\\n        }\\n        return dummy.next;\\n    }\\n}\",\"cpp\":\"class Solution {\\npublic:\\n    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {\\n        ListNode dummy(0);\\n        ListNode* curr = &dummy;\\n        int carry = 0;\\n        while (l1 || l2 || carry) {\\n            int sum = (l1 ? l1->val : 0) + (l2 ? l2->val : 0) + carry;\\n            carry = sum / 10;\\n            curr->next = new ListNode(sum % 10);\\n            curr = curr->next;\\n            if (l1) l1 = l1->next;\\n            if (l2) l2 = l2->next;\\n        }\\n        return dummy.next;\\n    }\\n};\"}",
