    "title": "Merge k Sorted Lists",
    "slug": "merge-k-sorted-lists",
    "difficulty": "Hard",
    "category": "Linked List",
    "description": "You are given an array of k linked-lists lists, each linked-list is sorted in ascending order. Merge all the linked-lists into one sorted linked-list and return it.",
    "examples": "[{\"input\":\"lists = [[1,4,5],[1,3,4],[2,6]]\",\"output\":\"[1,1,2,3,4,4,5,6]\",\"explanation\":\"All k lists merged in sorted order.\"},{\"input\":\"lists = []\",\"output\":\"[]\",\"explanation\":\"Empty array of lists.\"}]",
    "constraints": "[\"k == lists.length\",\"0 <= k <= 10^4\",\"0 <= lists[i].length <= 500\",\"-10^4 <= lists[i][j] <= 10^4\",\"lists[i] is sorted in ascending order.\"]",
    "hints": "[\"Use a min-heap priority queue storing current heads of all k lists in O(N log k) time.\",\"Alternatively, use divide-and-conquer to merge pairs of lists.\"]",
    "starterCode": "{\"javascript\":\"function mergeKLists(lists) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def mergeKLists(lists):\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public ListNode mergeKLists(ListNode[] lists) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    ListNode* mergeKLists(vector<ListNode*>& lists) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function mergeKLists(lists) {\\n  if (!lists.length) return null;\\n  while (lists.length > 1) {\\n    const merged = [];\\n    for (let i = 0; i < lists.length; i += 2) {\\n      const l1 = lists[i], l2 = i + 1 < lists.length ? lists[i + 1] : null;\\n      merged.push(mergeTwo(l1, l2));\\n    }\\n    lists = merged;\\n  }\\n  return lists[0];\\n  function mergeTwo(l1, l2) {\\n    const dummy = { val: 0, next: null };\\n    let tail = dummy;\\n    while (l1 && l2) {\\n      if (l1.val <= l2.val) { tail.next = l1; l1 = l1.next; }\\n      else { tail.next = l2; l2 = l2.next; }\\n      tail = tail.next;\\n    }\\n    tail.next = l1 || l2;\\n    return dummy.next;\\n  }\\n}\",\"python\":\"import heapq\\n\\ndef mergeKLists(lists):\\n    h = []\\n    for i, node in enumerate(lists):\\n        if node: heapq.heappush(h, (node.val, i, node))\\n    dummy = ListNode(0)\\n    curr = dummy\\n    while h:\\n        val, i, node = heapq.heappop(h)\\n        curr.next = node\\n        curr = curr.next\\n        if node.next:\\n            heapq.heappush(h, (node.next.val, i, node.next))\\n    return dummy.next\",\"java\":\"class Solution {\\n    public ListNode mergeKLists(ListNode[] lists) {\\n        if (lists == null || lists.length == 0) return null;\\n        java.util.PriorityQueue<ListNode> pq = new java.util.PriorityQueue<>((a, b) -> a.val - b.val);\\n        for (ListNode node : lists) if (node != null) pq.offer(node);\\n        ListNode dummy = new ListNode(0);\\n        ListNode curr = dummy;\\n        while (!pq.isEmpty()) {\\n            ListNode minNode = pq.poll();\\n            curr.next = minNode;\\n            curr = curr.next;\\n            if (minNode.next != null) pq.offer(minNode.next);\\n        }\\n        return dummy.next;\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <queue>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    ListNode* mergeKLists(vector<ListNode*>& lists) {\\n        auto cmp = [](ListNode* a, ListNode* b) { return a->val > b->val; };\\n        priority_queue<ListNode*, vector<ListNode*>, decltype(cmp)> pq(cmp);\\n        for (auto node : lists) if (node) pq.push(node);\\n        ListNode dummy(0);\\n        ListNode* curr = &dummy;\\n        while (!pq.empty()) {\\n            ListNode* minNode = pq.top(); pq.pop();\\n            curr->next = minNode;\\n            curr = curr->next;\\n            if (minNode->next) pq.push(minNode->next);\\n        }\\n        return dummy.next;\\n    }\\n};\"}",
    "testCases": "[{\"input\":\"[[1,4,5],[1,3,4],[2,6]]\",\"expectedOutput\":\"[1,1,2,3,4,4,5,6]\"},{\"input\":\"[]\",\"expectedOutput\":\"[]\"},{\"input\":\"Edge case input\",\"expectedOutput\":\"Expected Edge\"}]",
    "relatedSkillName": "Data Structures & Algorithms (DSA)",
    "contentReady": true
