    "description": "Given the head of a linked list, reverse the nodes of the list k at a time, and return the modified list. k is a positive integer and is less than or equal to the length of the linked list. Nodes that are not a multiple of k should remain as is.",
    "examples": "[{\"input\":\"head = [1,2,3,4,5], k = 2\",\"output\":\"[2,1,4,3,5]\",\"explanation\":\"Reversed in pairs.\"},{\"input\":\"head = [1,2,3,4,5], k = 3\",\"output\":\"[3,2,1,4,5]\",\"explanation\":\"First group of 3 reversed, remaining 2 untouched.\"}]",
    "constraints": "[\"The number of nodes in the list is n.\",\"1 <= k <= n <= 5000\",\"0 <= Node.val <= 1000\"]",
    "hints": "[\"Count k nodes ahead. If fewer than k nodes remain, stop.\",\"Reverse the sublist of k nodes and stitch back to groupPrev.\"]",
    "starterCode": "{\"javascript\":\"function reverseKGroup(head, k) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def reverseKGroup(head, k: int):\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public ListNode reverseKGroup(ListNode head, int k) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    ListNode* reverseKGroup(ListNode* head, int k) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function reverseKGroup(head, k) {\\n  const dummy = { val: 0, next: head };\\n  let groupPrev = dummy;\\n  while (true) {\\n    let kth = groupPrev;\\n    for (let i = 0; i < k && kth; i++) kth = kth.next;\\n    if (!kth) break;\\n    const groupNext = kth.next;\\n    let prev = groupNext, curr = groupPrev.next;\\n    while (curr !== groupNext) {\\n      const temp = curr.next;\\n      curr.next = prev;\\n      prev = curr;\\n      curr = temp;\\n    }\\n    const temp = groupPrev.next;\\n    groupPrev.next = kth;\\n    groupPrev = temp;\\n  }\\n  return dummy.next;\\n}\",\"python\":\"def reverseKGroup(head, k: int):\\n    dummy = ListNode(0, head)\\n    group_prev = dummy\\n    while True:\\n        kth = group_prev\\n        for _ in range(k):\\n            kth = kth.next\\n            if not kth: return dummy.next\\n        group_next = kth.next\\n        prev, curr = group_next, group_prev.next\\n        while curr != group_next:\\n            tmp = curr.next\\n            curr.next = prev\\n            prev = curr\\n            curr = tmp\\n        tmp = group_prev.next\\n        group_prev.next = kth\\n        group_prev = tmp\\n    return dummy.next\",\"java\":\"class Solution {\\n    public ListNode reverseKGroup(ListNode head, int k) {\\n        ListNode dummy = new ListNode(0, head);\\n        ListNode groupPrev = dummy;\\n        while (true) {\\n            ListNode kth = groupPrev;\\n            for (int i = 0; i < k && kth != null; i++) kth = kth.next;\\n            if (kth == null) break;\\n            ListNode groupNext = kth.next;\\n            ListNode prev = groupNext, curr = groupPrev.next;\\n            while (curr != groupNext) {\\n                ListNode tmp = curr.next;\\n                curr.next = prev;\\n                prev = curr;\\n                curr = tmp;\\n            }\\n            ListNode tmp = groupPrev.next;\\n            groupPrev.next = kth;\\n            groupPrev = tmp;\\n        }\\n        return dummy.next;\\n    }\\n}\",\"cpp\":\"class Solution {\\npublic:\\n    ListNode* reverseKGroup(ListNode* head, int k) {\\n        ListNode dummy(0, head);\\n        ListNode* groupPrev = &dummy;\\n        while (true) {\\n            ListNode* kth = groupPrev;\\n            for (int i = 0; i < k && kth; i++) kth = kth->next;\\n            if (!kth) break;\\n            ListNode* groupNext = kth->next;\\n            ListNode *prev = groupNext, *curr = groupPrev->next;\\n            while (curr != groupNext) {\\n                ListNode* tmp = curr->next;\\n                curr->next = prev;\\n                prev = curr;\\n                curr = tmp;\\n            }\\n            ListNode* tmp = groupPrev->next;\\n            groupPrev->next = kth;\\n            groupPrev = tmp;\\n        }\\n        return dummy.next;\\n    }\\n};\"}",
