    "starterCode": "{\"javascript\":\"function isValid(s) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def isValid(s: str) -> bool:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public boolean isValid(String s) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    bool isValid(string s) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function isValid(s) {\\n  const stack = [];\\n  const pairs = { \\\")\\\": \\\"(\\\", \\\"}\\\": \\\"{\\\", \\\"]\\\": \\\"[\\\" };\\n  for (const c of s) {\\n    if (c === \\\"(\\\" || c === \\\"{\\\" || c === \\\"[\\\") stack.push(c);\\n    else if (!stack.length || stack.pop() !== pairs[c]) return false;\\n  }\\n  return stack.length === 0;\\n}\",\"python\":\"def isValid(s: str) -> bool:\\n    stack = []\\n    pairs = {\\\")\\\": \\\"(\\\", \\\"}\\\": \\\"{\\\", \\\"]\\\": \\\"[\\\"}\\n    for c in s:\\n        if c in pairs.values(): stack.append(c)\\n        elif not stack or stack.pop() != pairs[c]: return False\\n    return not stack\",\"java\":\"class Solution {\\n    public boolean isValid(String s) {\\n        java.util.Stack<Character> stack = new java.util.Stack<>();\\n        for (char c : s.toCharArray()) {\\n            if (c == '(') stack.push(')');\\n            else if (c == '{') stack.push('}');\\n            else if (c == '[') stack.push(']');\\n            else if (stack.isEmpty() || stack.pop() != c) return false;\\n        }\\n        return stack.isEmpty();\\n    }\\n}\",\"cpp\":\"#include <string>\\n#include <stack>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    bool isValid(string s) {\\n        stack<char> st;\\n        for (char c : s) {\\n            if (c == '(') st.push(')');\\n            else if (c == '{') st.push('}');\\n            else if (c == '[') st.push(']');\\n            else if (st.empty() || st.top() != c) return false;\\n            else st.pop();\\n        }\\n        return st.empty();\\n    }\\n};\"}",
