    "referenceSolution": "{\"javascript\":\"class MinStack {\\n  constructor() {\\n    this.stack = [];\\n  }\\n  push(val) {\\n    const min = !this.stack.length ? val : Math.min(val, this.getMin());\\n    this.stack.push({ val, min });\\n  }\\n  pop() {\\n    this.stack.pop();\\n  }\\n  top() {\\n    return this.stack[this.stack.length - 1].val;\\n  }\\n  getMin() {\\n    return this.stack[this.stack.length - 1].min;\\n  }\\n}\",\"python\":\"class MinStack:\\n    def __init__(self):\\n        self.stack = []\\n    def push(self, val: int) -> None:\\n        m = val if not self.stack else min(val, self.stack[-1][1])\\n        self.stack.append((val, m))\\n    def pop(self) -> None:\\n        self.stack.pop()\\n    def top(self) -> int:\\n        return self.stack[-1][0]\\n    def getMin(self) -> int:\\n        return self.stack[-1][1]\",\"java\":\"class MinStack {\\n    private java.util.Stack<int[]> stack = new java.util.Stack<>();\\n    public void push(int val) {\\n        int min = stack.isEmpty() ? val : Math.min(val, stack.peek()[1]);\\n        stack.push(new int[]{val, min});\\n    }\\n    public void pop() { stack.pop(); }\\n    public int top() { return stack.peek()[0]; }\\n    public int getMin() { return stack.peek()[1]; }\\n}\",\"cpp\":\"#include <stack>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass MinStack {\\n    stack<pair<int, int>> st;\\npublic:\\n    void push(int val) {\\n        int m = st.empty() ? val : min(val, st.top().second);\\n        st.push({val, m});\\n    }\\n    void pop() { st.pop(); }\\n    int top() { return st.top().first; }\\n    int getMin() { return st.top().second; }\\n};\"}",
