    "starterCode": "{\"javascript\":\"function dailyTemperatures(temperatures) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def dailyTemperatures(temperatures: list[int]) -> list[int]:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int[] dailyTemperatures(int[] temperatures) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    vector<int> dailyTemperatures(vector<int>& temperatures) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function dailyTemperatures(temperatures) {\\n  const res = new Array(temperatures.length).fill(0);\\n  const stack = []; // indices\\n  for (let i = 0; i < temperatures.length; i++) {\\n    while (stack.length && temperatures[i] > temperatures[stack[stack.length - 1]]) {\\n      const prevIdx = stack.pop();\\n      res[prevIdx] = i - prevIdx;\\n    }\\n    stack.push(i);\\n  }\\n  return res;\\n}\",\"python\":\"def dailyTemperatures(temperatures: list[int]) -> list[int]:\\n    res = [0] * len(temperatures)\\n    stack = []\\n    for i, t in enumerate(temperatures):\\n        while stack and t > temperatures[stack[-1]]:\\n            prev = stack.pop()\\n            res[prev] = i - prev\\n        stack.append(i)\\n    return res\",\"java\":\"class Solution {\\n    public int[] dailyTemperatures(int[] temperatures) {\\n        int[] res = new int[temperatures.length];\\n        java.util.Stack<Integer> stack = new java.util.Stack<>();\\n        for (int i = 0; i < temperatures.length; i++) {\\n            while (!stack.isEmpty() && temperatures[i] > temperatures[stack.peek()]) {\\n                int prev = stack.pop();\\n                res[prev] = i - prev;\\n            }\\n            stack.push(i);\\n        }\\n        return res;\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <stack>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    vector<int> dailyTemperatures(vector<int>& temperatures) {\\n        vector<int> res(temperatures.size(), 0);\\n        stack<int> st;\\n        for (size_t i = 0; i < temperatures.size(); i++) {\\n            while (!st.empty() && temperatures[i] > temperatures[st.top()]) {\\n                int prev = st.top(); st.pop();\\n                res[prev] = i - prev;\\n            }\\n            st.push(i);\\n        }\\n        return res;\\n    }\\n};\"}",
