    "hints": "[\"Maintain a monotonic increasing stack of indices.\",\"When a smaller height is found, pop the stack and compute width = stack.isEmpty() ? i : i - stack.peek() - 1.\"]",
    "starterCode": "{\"javascript\":\"function largestRectangleArea(heights) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def largestRectangleArea(heights: list[int]) -> int:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int largestRectangleArea(int[] heights) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int largestRectangleArea(vector<int>& heights) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function largestRectangleArea(heights) {\\n  const stack = [];\\n  let maxArea = 0;\\n  heights.push(0);\\n  for (let i = 0; i < heights.length; i++) {\\n    while (stack.length && heights[i] < heights[stack[stack.length - 1]]) {\\n      const h = heights[stack.pop()];\\n      const w = stack.length === 0 ? i : i - stack[stack.length - 1] - 1;\\n      maxArea = Math.max(maxArea, h * w);\\n    }\\n    stack.push(i);\\n  }\\n  return maxArea;\\n}\",\"python\":\"def largestRectangleArea(heights: list[int]) -> int:\\n    stack = []\\n    max_area = 0\\n    heights.append(0)\\n    for i, h in enumerate(heights):\\n        while stack and h < heights[stack[-1]]:\\n            height = heights[stack.pop()]\\n            width = i if not stack else i - stack[-1] - 1\\n            max_area = max(max_area, height * width)\\n        stack.append(i)\\n    return max_area\",\"java\":\"class Solution {\\n    public int largestRectangleArea(int[] heights) {\\n        java.util.Stack<Integer> stack = new java.util.Stack<>();\\n        int maxArea = 0, n = heights.length;\\n        for (int i = 0; i <= n; i++) {\\n            int h = i == n ? 0 : heights[i];\\n            while (!stack.isEmpty() && h < heights[stack.peek()]) {\\n                int height = heights[stack.pop()];\\n                int width = stack.isEmpty() ? i : i - stack.peek() - 1;\\n                maxArea = Math.max(maxArea, height * width);\\n            }\\n            stack.push(i);\\n        }\\n        return maxArea;\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <stack>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int largestRectangleArea(vector<int>& heights) {\\n        stack<int> st;\\n        int maxArea = 0;\\n        heights.push_back(0);\\n        for (size_t i = 0; i < heights.size(); i++) {\\n            while (!st.empty() && heights[i] < heights[st.top()]) {\\n                int h = heights[st.top()]; st.pop();\\n                int w = st.empty() ? i : i - st.top() - 1;\\n                maxArea = max(maxArea, h * w);\\n            }\\n            st.push(i);\\n        }\\n        return maxArea;\\n    }\\n};\"}",
