    "referenceSolution": "{\"javascript\":\"class MyQueue {\\n  constructor() {\\n    this.inStack = [];\\n    this.outStack = [];\\n  }\\n  push(x) {\\n    this.inStack.push(x);\\n  }\\n  pop() {\\n    this.peek();\\n    return this.outStack.pop();\\n  }\\n  peek() {\\n    if (!this.outStack.length) {\\n      while (this.inStack.length) this.outStack.push(this.inStack.pop());\\n    }\\n    return this.outStack[this.outStack.length - 1];\\n  }\\n  empty() {\\n    return !this.inStack.length && !this.outStack.length;\\n  }\\n}\",\"python\":\"class MyQueue:\\n    def __init__(self):\\n        self.in_stack = []\\n        self.out_stack = []\\n    def push(self, x: int) -> None:\\n        self.in_stack.append(x)\\n    def pop(self) -> int:\\n        self.peek()\\n        return self.out_stack.pop()\\n    def peek(self) -> int:\\n        if not self.out_stack:\\n            while self.in_stack:\\n                self.out_stack.append(self.in_stack.pop())\\n        return self.out_stack[-1]\\n    def empty(self) -> bool:\\n        return not self.in_stack and not self.out_stack\",\"java\":\"class MyQueue {\\n    private java.util.Stack<Integer> in = new java.util.Stack<>();\\n    private java.util.Stack<Integer> out = new java.util.Stack<>();\\n    public void push(int x) { in.push(x); }\\n    public int pop() { peek(); return out.pop(); }\\n    public int peek() {\\n        if (out.isEmpty()) while (!in.isEmpty()) out.push(in.pop());\\n        return out.peek();\\n    }\\n    public boolean empty() { return in.isEmpty() && out.isEmpty(); }\\n}\",\"cpp\":\"#include <stack>\\nusing namespace std;\\n\\nclass MyQueue {\\n    stack<int> inSt, outSt;\\npublic:\\n    void push(int x) { inSt.push(x); }\\n    int pop() { int v = peek(); outSt.pop(); return v; }\\n    int peek() {\\n        if (outSt.empty()) {\\n            while (!inSt.empty()) { outSt.push(inSt.top()); inSt.pop(); }\\n        }\\n        return outSt.top();\\n    }\\n    bool empty() { return inSt.empty() && outSt.empty(); }\\n};\"}",
