    "starterCode": "{\"javascript\":\"class RecentCounter {\\n  constructor() {\\n    // Initialize ping queue\\n  }\\n  ping(t) {\\n    // Add ping at time t and return count in [t-3000, t]\\n  }\\n}\",\"python\":\"from collections import deque\\n\\nclass RecentCounter:\\n    def __init__(self):\\n        pass\\n\\n    def ping(self, t: int) -> int:\\n        pass\",\"java\":\"import java.util.LinkedList;\\nimport java.util.Queue;\\n\\nclass RecentCounter {\\n    public RecentCounter() {\\n    }\\n    \\n    public int ping(int t) {\\n        return 0;\\n    }\\n}\",\"cpp\":\"#include <queue>\\nusing namespace std;\\n\\nclass RecentCounter {\\npublic:\\n    RecentCounter() {\\n    }\\n    \\n    int ping(int t) {\\n        return 0;\\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"class RecentCounter {\\n  constructor() {\\n    this.queue = [];\\n  }\\n  ping(t) {\\n    this.queue.push(t);\\n    while (this.queue[0] < t - 3000) this.queue.shift();\\n    return this.queue.length;\\n  }\\n}\",\"python\":\"from collections import deque\\n\\nclass RecentCounter:\\n    def __init__(self):\\n        self.q = deque()\\n    def ping(self, t: int) -> int:\\n        self.q.append(t)\\n        while self.q[0] < t - 3000:\\n            self.q.popleft()\\n        return len(self.q)\",\"java\":\"class RecentCounter {\\n    private java.util.Queue<Integer> q = new java.util.LinkedList<>();\\n    public int ping(int t) {\\n        q.offer(t);\\n        while (q.peek() < t - 3000) q.poll();\\n        return q.size();\\n    }\\n}\",\"cpp\":\"#include <queue>\\nusing namespace std;\\n\\nclass RecentCounter {\\n    queue<int> q;\\npublic:\\n    int ping(int t) {\\n        q.push(t);\\n        while (q.front() < t - 3000) q.pop();\\n        return q.size();\\n    }\\n};\"}",
