    "difficulty": "Medium",
    "category": "Queue",
    "description": "Design your implementation of the circular queue. A circular queue is a linear data structure based on FIFO principle and the last position is connected back to the first position to make a circle.",
    "examples": "[{\"input\":\"[\\\"MyCircularQueue\\\",\\\"enQueue\\\",\\\"enQueue\\\",\\\"enQueue\\\",\\\"enQueue\\\",\\\"Rear\\\",\\\"isFull\\\",\\\"deQueue\\\",\\\"enQueue\\\",\\\"Rear\\\"]\\n[[3],[1],[2],[3],[4],[],[],[],[4],[]]\",\"output\":\"[null,true,true,true,false,3,true,true,true,4]\",\"explanation\":\"Circular queue bounded array operations.\"},{\"input\":\"input = []\",\"output\":\"[]\",\"explanation\":\"Boundary empty collection case.\"}]",
    "constraints": "[\"0 <= value <= 1000\",\"1 <= k <= 1000\",\"At most 3000 calls will be made to enQueue, deQueue, Front, Rear, isEmpty, and isFull.\"]",
    "hints": "[\"Use fixed-size array of size k with head, count pointers.\",\"Calculate tail index using (head + count - 1) % k.\"]",
    "starterCode": "{\"javascript\":\"class MyCircularQueue {\\n  constructor(k) {\\n    // Initialize circular queue of size k\\n  }\\n  enQueue(value) {\\n    // Insert element into circular queue\\n  }\\n  deQueue() {\\n    // Delete element from circular queue\\n  }\\n  Front() {\\n    // Get front item\\n  }\\n  Rear() {\\n    // Get last item\\n  }\\n  isEmpty() {\\n    // Check if empty\\n  }\\n  isFull() {\\n    // Check if full\\n  }\\n}\",\"python\":\"class MyCircularQueue:\\n    def __init__(self, k: int):\\n        pass\\n\\n    def enQueue(self, value: int) -> bool:\\n        pass\\n\\n    def deQueue(self) -> bool:\\n        pass\\n\\n    def Front(self) -> int:\\n        pass\\n\\n    def Rear(self) -> int:\\n        pass\\n\\n    def isEmpty(self) -> bool:\\n        pass\\n\\n    def isFull(self) -> bool:\\n        pass\",\"java\":\"class MyCircularQueue {\\n    public MyCircularQueue(int k) {\\n    }\\n    \\n    public boolean enQueue(int value) {\\n        return false;\\n    }\\n    \\n    public boolean deQueue() {\\n        return false;\\n    }\\n    \\n    public int Front() {\\n        return -1;\\n    }\\n    \\n    public int Rear() {\\n        return -1;\\n    }\\n    \\n    public boolean isEmpty() {\\n        return true;\\n    }\\n    \\n    public boolean isFull() {\\n        return false;\\n    }\\n}\",\"cpp\":\"#include <vector>\\nusing namespace std;\\n\\nclass MyCircularQueue {\\npublic:\\n    MyCircularQueue(int k) {\\n    }\\n    \\n    bool enQueue(int value) {\\n        return false;\\n    }\\n    \\n    bool deQueue() {\\n        return false;\\n    }\\n    \\n    int Front() {\\n        return -1;\\n    }\\n    \\n    int Rear() {\\n        return -1;\\n    }\\n    \\n    bool isEmpty() {\\n        return true;\\n    }\\n    \\n    bool isFull() {\\n        return false;\\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"class MyCircularQueue {\\n  constructor(k) {\\n    this.k = k;\\n    this.arr = new Array(k);\\n    this.head = 0;\\n    this.count = 0;\\n  }\\n  enQueue(value) {\\n    if (this.isFull()) return false;\\n    this.arr[(this.head + this.count) % this.k] = value;\\n    this.count++;\\n    return true;\\n  }\\n  deQueue() {\\n    if (this.isEmpty()) return false;\\n    this.head = (this.head + 1) % this.k;\\n    this.count--;\\n    return true;\\n  }\\n  Front() {\\n    return this.isEmpty() ? -1 : this.arr[this.head];\\n  }\\n  Rear() {\\n    return this.isEmpty() ? -1 : this.arr[(this.head + this.count - 1) % this.k];\\n  }\\n  isEmpty() { return this.count === 0; }\\n  isFull() { return this.count === this.k; }\\n}\",\"python\":\"class MyCircularQueue:\\n    def __init__(self, k: int):\\n        self.k = k\\n        self.arr = [0] * k\\n        self.head = self.count = 0\\n    def enQueue(self, value: int) -> bool:\\n        if self.isFull(): return False\\n        self.arr[(self.head + self.count) % self.k] = value\\n        self.count += 1\\n        return True\\n    def deQueue(self) -> bool:\\n        if self.isEmpty(): return False\\n        self.head = (self.head + 1) % self.k\\n        self.count -= 1\\n        return True\\n    def Front(self) -> int:\\n        return -1 if self.isEmpty() else self.arr[self.head]\\n    def Rear(self) -> int:\\n        return -1 if self.isEmpty() else self.arr[(self.head + self.count - 1) % self.k]\\n    def isEmpty(self) -> bool: return self.count == 0\\n    def isFull(self) -> bool: return self.count == self.k\",\"java\":\"class MyCircularQueue {\\n    private int[] data;\\n    private int head = 0, count = 0, k;\\n    public MyCircularQueue(int k) { this.k = k; data = new int[k]; }\\n    public boolean enQueue(int value) {\\n        if (isFull()) return false;\\n        data[(head + count) % k] = value; count++; return true;\\n    }\\n    public boolean deQueue() {\\n        if (isEmpty()) return false;\\n        head = (head + 1) % k; count--; return true;\\n    }\\n    public int Front() { return isEmpty() ? -1 : data[head]; }\\n    public int Rear() { return isEmpty() ? -1 : data[(head + count - 1) % k]; }\\n    public boolean isEmpty() { return count == 0; }\\n    public boolean isFull() { return count == k; }\\n}\",\"cpp\":\"#include <vector>\\nusing namespace std;\\n\\nclass MyCircularQueue {\\n    vector<int> data;\\n    int head = 0, count = 0, k;\\npublic:\\n    MyCircularQueue(int k) : data(k), k(k) {}\\n    bool enQueue(int value) {\\n        if (isFull()) return false;\\n        data[(head + count) % k] = value; count++; return true;\\n    }\\n    bool deQueue() {\\n        if (isEmpty()) return false;\\n        head = (head + 1) % k; count--; return true;\\n    }\\n    int Front() { return isEmpty() ? -1 : data[head]; }\\n    int Rear() { return isEmpty() ? -1 : data[(head + count - 1) % k]; }\\n    bool isEmpty() { return count == 0; }\\n    bool isFull() { return count == k; }\\n};\"}",
