    "referenceSolution": "{\"javascript\":\"class MyCircularDeque {\\n  constructor(k) {\\n    this.k = k;\\n    this.arr = new Array(k);\\n    this.head = 0;\\n    this.count = 0;\\n  }\\n  insertFront(value) {\\n    if (this.isFull()) return false;\\n    this.head = (this.head - 1 + this.k) % this.k;\\n    this.arr[this.head] = value;\\n    this.count++;\\n    return true;\\n  }\\n  insertLast(value) {\\n    if (this.isFull()) return false;\\n    this.arr[(this.head + this.count) % this.k] = value;\\n    this.count++;\\n    return true;\\n  }\\n  deleteFront() {\\n    if (this.isEmpty()) return false;\\n    this.head = (this.head + 1) % this.k;\\n    this.count--;\\n    return true;\\n  }\\n  deleteLast() {\\n    if (this.isEmpty()) return false;\\n    this.count--;\\n    return true;\\n  }\\n  getFront() { return this.isEmpty() ? -1 : this.arr[this.head]; }\\n  getRear() { return this.isEmpty() ? -1 : this.arr[(this.head + this.count - 1) % this.k]; }\\n  isEmpty() { return this.count === 0; }\\n  isFull() { return this.count === this.k; }\\n}\",\"python\":\"class MyCircularDeque:\\n    def __init__(self, k: int):\\n        self.k = k\\n        self.arr = [0] * k\\n        self.head = self.count = 0\\n    def insertFront(self, value: int) -> bool:\\n        if self.isFull(): return False\\n        self.head = (self.head - 1 + self.k) % self.k\\n        self.arr[self.head] = value\\n        self.count += 1\\n        return True\\n    def insertLast(self, value: int) -> bool:\\n        if self.isFull(): return False\\n        self.arr[(self.head + self.count) % self.k] = value\\n        self.count += 1\\n        return True\\n    def deleteFront(self) -> bool:\\n        if self.isEmpty(): return False\\n        self.head = (self.head + 1) % self.k\\n        self.count -= 1\\n        return True\\n    def deleteLast(self) -> bool:\\n        if self.isEmpty(): return False\\n        self.count -= 1\\n        return True\\n    def getFront(self) -> int: return -1 if self.isEmpty() else self.arr[self.head]\\n    def getRear(self) -> int: return -1 if self.isEmpty() else self.arr[(self.head + self.count - 1) % self.k]\\n    def isEmpty(self) -> bool: return self.count == 0\\n    def isFull(self) -> bool: return self.count == self.k\",\"java\":\"class MyCircularDeque {\\n    private int[] data;\\n    private int head = 0, count = 0, k;\\n    public MyCircularDeque(int k) { this.k = k; data = new int[k]; }\\n    public boolean insertFront(int value) {\\n        if (isFull()) return false;\\n        head = (head - 1 + k) % k; data[head] = value; count++; return true;\\n    }\\n    public boolean insertLast(int value) {\\n        if (isFull()) return false;\\n        data[(head + count) % k] = value; count++; return true;\\n    }\\n    public boolean deleteFront() {\\n        if (isEmpty()) return false;\\n        head = (head + 1) % k; count--; return true;\\n    }\\n    public boolean deleteLast() {\\n        if (isEmpty()) return false;\\n        count--; return true;\\n    }\\n    public int getFront() { return isEmpty() ? -1 : data[head]; }\\n    public int getRear() { return isEmpty() ? -1 : data[(head + count - 1) % k]; }\\n    public boolean isEmpty() { return count == 0; }\\n    public boolean isFull() { return count == k; }\\n}\",\"cpp\":\"#include <vector>\\nusing namespace std;\\n\\nclass MyCircularDeque {\\n    vector<int> data;\\n    int head = 0, count = 0, k;\\npublic:\\n    MyCircularDeque(int k) : data(k), k(k) {}\\n    bool insertFront(int value) {\\n        if (isFull()) return false;\\n        head = (head - 1 + k) % k; data[head] = value; count++; return true;\\n    }\\n    bool insertLast(int value) {\\n        if (isFull()) return false;\\n        data[(head + count) % k] = value; count++; return true;\\n    }\\n    bool deleteFront() {\\n        if (isEmpty()) return false;\\n        head = (head + 1) % k; count--; return true;\\n    }\\n    bool deleteLast() {\\n        if (isEmpty()) return false;\\n        count--; return true;\\n    }\\n    int getFront() { return isEmpty() ? -1 : data[head]; }\\n    int getRear() { return isEmpty() ? -1 : data[(head + count - 1) % k]; }\\n    bool isEmpty() { return count == 0; }\\n    bool isFull() { return count == k; }\\n};\"}",
