    "constraints": "[\"1 <= nums.length <= 10^5\",\"-10^5 <= nums[i] <= 10^5\",\"1 <= k <= 10^9\"]",
    "hints": "[\"Compute prefix sums P where P[i] is sum of first i elements.\",\"Maintain a monotonic increasing deque of indices of prefix sums.\"]",
    "starterCode": "{\"javascript\":\"function shortestSubarray(nums, k) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def shortestSubarray(nums: list[int], k: int) -> int:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int shortestSubarray(int[] nums, int k) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int shortestSubarray(vector<int>& nums, int k) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function shortestSubarray(nums, k) {\\n  const n = nums.length;\\n  const P = new Array(n + 1).fill(0);\\n  for (let i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];\\n  let minLen = Infinity;\\n  const deque = [];\\n  for (let y = 0; y <= n; y++) {\\n    while (deque.length && P[y] <= P[deque[deque.length - 1]]) deque.pop();\\n    while (deque.length && P[y] - P[deque[0]] >= k) {\\n      minLen = Math.min(minLen, y - deque.shift());\\n    }\\n    deque.push(y);\\n  }\\n  return minLen <= n ? minLen : -1;\\n}\",\"python\":\"from collections import deque\\n\\ndef shortestSubarray(nums: list[int], k: int) -> int:\\n    n = len(nums)\\n    P = [0] * (n + 1)\\n    for i, x in enumerate(nums): P[i + 1] = P[i] + x\\n    min_len = float(\\\"inf\\\")\\n    q = deque()\\n    for y, py in enumerate(P):\\n        while q and py <= P[q[-1]]: q.pop()\\n        while q and py - P[q[0]] >= k:\\n            min_len = min(min_len, y - q.popleft())\\n        q.append(y)\\n    return min_len if min_len <= n else -1\",\"java\":\"class Solution {\\n    public int shortestSubarray(int[] nums, int k) {\\n        int n = nums.length;\\n        long[] P = new long[n + 1];\\n        for (int i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];\\n        int minLen = n + 1;\\n        java.util.Deque<Integer> dq = new java.util.ArrayDeque<>();\\n        for (int y = 0; y <= n; y++) {\\n            while (!dq.isEmpty() && P[y] <= P[dq.peekLast()]) dq.pollLast();\\n            while (!dq.isEmpty() && P[y] - P[dq.peekFirst()] >= k) {\\n                minLen = Math.min(minLen, y - dq.pollFirst());\\n            }\\n            dq.offerLast(y);\\n        }\\n        return minLen <= n ? minLen : -1;\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <deque>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int shortestSubarray(vector<int>& nums, int k) {\\n        int n = nums.size();\\n        vector<long long> P(n + 1, 0);\\n        for (int i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];\\n        int minLen = n + 1;\\n        deque<int> dq;\\n        for (int y = 0; y <= n; y++) {\\n            while (!dq.empty() && P[y] <= P[dq.back()]) dq.pop_back();\\n            while (!dq.empty() && P[y] - P[dq.front()] >= k) {\\n                minLen = min(minLen, y - dq.front());\\n                dq.pop_front();\\n            }\\n            dq.push_back(y);\\n        }\\n        return minLen <= n ? minLen : -1;\\n    }\\n};\"}",
