    "starterCode": "{\"javascript\":\"function myPow(x, n) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def myPow(x: float, n: int) -> float:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public double myPow(double x, int n) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    double myPow(double x, int n) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function myPow(x, n) {\\n  let p = n;\\n  if (p < 0) { x = 1 / x; p = -p; }\\n  let res = 1;\\n  while (p > 0) {\\n    if (p % 2 === 1) res *= x;\\n    x *= x;\\n    p = Math.floor(p / 2);\\n  }\\n  return res;\\n}\",\"python\":\"def myPow(x: float, n: int) -> float:\\n    if n < 0: x, n = 1 / x, -n\\n    res = 1\\n    while n > 0:\\n        if n % 2 == 1: res *= x\\n        x *= x\\n        n //= 2\\n    return res\",\"java\":\"class Solution {\\n    public double myPow(double x, int n) {\\n        long p = n;\\n        if (p < 0) { x = 1 / x; p = -p; }\\n        double res = 1;\\n        while (p > 0) {\\n            if (p % 2 == 1) res *= x;\\n            x *= x;\\n            p /= 2;\\n        }\\n        return res;\\n    }\\n}\",\"cpp\":\"class Solution {\\npublic:\\n    double myPow(double x, int n) {\\n        long long p = n;\\n        if (p < 0) { x = 1 / x; p = -p; }\\n        double res = 1;\\n        while (p > 0) {\\n            if (p % 2 == 1) res *= x;\\n            x *= x;\\n            p /= 2;\\n        }\\n        return res;\\n    }\\n};\"}",
