    "description": "Given a string containing digits from 2-9 inclusive, return all possible letter combinations that the number could represent. Return the answer in any order. A mapping of digits to letters (just like on the telephone buttons) is given.",
    "examples": "[{\"input\":\"digits = \\\"23\\\"\",\"output\":\"[\\\"ad\\\",\\\"ae\\\",\\\"af\\\",\\\"bd\\\",\\\"be\\\",\\\"bf\\\",\\\"cd\\\",\\\"ce\\\",\\\"cf\\\"]\",\"explanation\":\"All combinations for 2 and 3.\"},{\"input\":\"digits = \\\"\\\"\",\"output\":\"[]\",\"explanation\":\"Empty input.\"}]",
    "constraints": "[\"0 <= digits.length <= 4\",\"digits[i] is a digit in the range ['2', '9'].\"]",
    "hints": "[\"Create a phone keypad mapping (e.g., 2 -> \\\"abc\\\", 3 -> \\\"def\\\").\",\"Use backtracking to build strings character by character.\"]",
    "starterCode": "{\"javascript\":\"function letterCombinations(digits) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def letterCombinations(digits: str) -> list[str]:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public void solve() {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    vector<string> letterCombinations(string digits) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function letterCombinations(digits) {\\n  if (!digits) return [];\\n  const map = { \\\"2\\\": \\\"abc\\\", \\\"3\\\": \\\"def\\\", \\\"4\\\": \\\"ghi\\\", \\\"5\\\": \\\"jkl\\\", \\\"6\\\": \\\"mno\\\", \\\"7\\\": \\\"pqrs\\\", \\\"8\\\": \\\"tuv\\\", \\\"9\\\": \\\"wxyz\\\" };\\n  const res = [];\\n  function backtrack(idx, path) {\\n    if (idx === digits.length) { res.push(path); return; }\\n    for (const letter of map[digits[idx]]) {\\n      backtrack(idx + 1, path + letter);\\n    }\\n  }\\n  backtrack(0, \\\"\\\");\\n  return res;\\n}\",\"python\":\"def letterCombinations(digits: str) -> list[str]:\\n    if not digits: return []\\n    mapping = {\\\"2\\\": \\\"abc\\\", \\\"3\\\": \\\"def\\\", \\\"4\\\": \\\"ghi\\\", \\\"5\\\": \\\"jkl\\\", \\\"6\\\": \\\"mno\\\", \\\"7\\\": \\\"pqrs\\\", \\\"8\\\": \\\"tuv\\\", \\\"9\\\": \\\"wxyz\\\"}\\n    res = []\\n    def backtrack(idx, path):\\n        if idx == len(digits):\\n            res.append(path)\\n            return\\n        for letter in mapping[digits[idx]]:\\n            backtrack(idx + 1, path + letter)\\n    backtrack(0, \\\"\\\")\\n    return res\",\"java\":\"class Solution {\\n    public java.util.List<String> letterCombinations(String digits) {\\n        if (digits == null || digits.isEmpty()) return new java.util.ArrayList<>();\\n        String[] map = {\\\"\\\", \\\"\\\", \\\"abc\\\", \\\"def\\\", \\\"ghi\\\", \\\"jkl\\\", \\\"mno\\\", \\\"pqrs\\\", \\\"tuv\\\", \\\"wxyz\\\"};\\n        java.util.List<String> res = new java.util.ArrayList<>();\\n        backtrack(digits, 0, new StringBuilder(), res, map);\\n        return res;\\n    }\\n    private void backtrack(String d, int idx, StringBuilder path, java.util.List<String> res, String[] map) {\\n        if (idx == d.length()) { res.add(path.toString()); return; }\\n        String letters = map[d.charAt(idx) - '0'];\\n        for (char c : letters.toCharArray()) {\\n            path.append(c);\\n            backtrack(d, idx + 1, path, res, map);\\n            path.deleteCharAt(path.length() - 1);\\n        }\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\nusing namespace std;\\n\\nclass Solution {\\n    vector<string> map = {\\\"\\\", \\\"\\\", \\\"abc\\\", \\\"def\\\", \\\"ghi\\\", \\\"jkl\\\", \\\"mno\\\", \\\"pqrs\\\", \\\"tuv\\\", \\\"wxyz\\\"};\\n    vector<string> res;\\npublic:\\n    vector<string> letterCombinations(string digits) {\\n        if (digits.empty()) return {};\\n        string path = \\\"\\\";\\n        backtrack(digits, 0, path);\\n        return res;\\n    }\\n    void backtrack(const string& d, int idx, string& path) {\\n        if (idx == (int)d.size()) { res.push_back(path); return; }\\n        for (char c : map[d[idx] - '0']) {\\n            path.push_back(c);\\n            backtrack(d, idx + 1, path);\\n            path.pop_back();\\n        }\\n    }\\n};\"}",
