    "title": "Subsets",
    "slug": "subsets",
    "difficulty": "Medium",
    "category": "Backtracking",
    "description": "Given an integer array nums of unique elements, return all possible subsets (the power set). The solution set must not contain duplicate subsets. Return the solution in any order.",
    "examples": "[{\"input\":\"nums = [1,2,3]\",\"output\":\"[[],[1],[2],[1,2],[3],[1,3],[2,3],[1,2,3]]\",\"explanation\":\"All 2^3 = 8 subsets.\"},{\"input\":\"nums = [0]\",\"output\":\"[[],[0]]\",\"explanation\":\"Power set of single element.\"}]",
    "constraints": "[\"1 <= nums.length <= 10\",\"-10 <= nums[i] <= 10\",\"All the numbers of nums are unique.\"]",
    "hints": "[\"At each step, push a copy of current path to result.\",\"Iterate from start to len(nums), pick nums[i], recurse with i + 1, and backtrack.\"]",
    "starterCode": "{\"javascript\":\"function subsets(nums) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def subsets(nums: list[int]) -> list[list[int]]:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public void solve() {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    vector<vector<int>> subsets(vector<int>& nums) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function subsets(nums) {\\n  const res = [];\\n  function backtrack(start, path) {\\n    res.push([...path]);\\n    for (let i = start; i < nums.length; i++) {\\n      path.push(nums[i]);\\n      backtrack(i + 1, path);\\n      path.pop();\\n    }\\n  }\\n  backtrack(0, []);\\n  return res;\\n}\",\"python\":\"def subsets(nums: list[int]) -> list[list[int]]:\\n    res = []\\n    def backtrack(start, path):\\n        res.append(list(path))\\n        for i in range(start, len(nums)):\\n            path.append(nums[i])\\n            backtrack(i + 1, path)\\n            path.pop()\\n    backtrack(0, [])\\n    return res\",\"java\":\"class Solution {\\n    public java.util.List<java.util.List<Integer>> subsets(int[] nums) {\\n        java.util.List<java.util.List<Integer>> res = new java.util.ArrayList<>();\\n        backtrack(0, nums, new java.util.ArrayList<>(), res);\\n        return res;\\n    }\\n    private void backtrack(int start, int[] nums, java.util.List<Integer> path, java.util.List<java.util.List<Integer>> res) {\\n        res.add(new java.util.ArrayList<>(path));\\n        for (int i = start; i < nums.length; i++) {\\n            path.add(nums[i]);\\n            backtrack(i + 1, nums, path, res);\\n            path.remove(path.size() - 1);\\n        }\\n    }\\n}\",\"cpp\":\"#include <vector>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    vector<vector<int>> subsets(vector<int>& nums) {\\n        vector<vector<int>> res;\\n        vector<int> path;\\n        auto backtrack = [&](auto& self, int start) -> void {\\n            res.push_back(path);\\n            for (size_t i = start; i < nums.size(); i++) {\\n                path.push_back(nums[i]);\\n                self(self, i + 1);\\n                path.pop_back();\\n            }\\n        };\\n        backtrack(backtrack, 0);\\n        return res;\\n    }\\n};\"}",
