    "referenceSolution": "{\"javascript\":\"function solveSudoku(board) {\\n  function isValid(r, c, ch) {\\n    for (let i = 0; i < 9; i++) {\\n      if (board[r][i] === ch || board[i][c] === ch) return false;\\n      const br = 3 * Math.floor(r / 3) + Math.floor(i / 3);\\n      const bc = 3 * Math.floor(c / 3) + (i % 3);\\n      if (board[br][bc] === ch) return false;\\n    }\\n    return true;\\n  }\\n  function solve() {\\n    for (let r = 0; r < 9; r++) {\\n      for (let c = 0; c < 9; c++) {\\n        if (board[r][c] === \\\".\\\") {\\n          for (let d = 1; d <= 9; d++) {\\n            const ch = String(d);\\n            if (isValid(r, c, ch)) {\\n              board[r][c] = ch;\\n              if (solve()) return true;\\n              board[r][c] = \\\".\\\";\\n            }\\n          }\\n          return false;\\n        }\\n      }\\n    }\\n    return true;\\n  }\\n  solve();\\n  return board;\\n}\",\"python\":\"def solveSudoku(board: list[list[str]]) -> None:\\n    def is_valid(r, c, ch):\\n        for i in range(9):\\n            if board[r][i] == ch or board[i][c] == ch: return False\\n            if board[3 * (r // 3) + i // 3][3 * (c // 3) + i % 3] == ch: return False\\n        return True\\n    def solve():\\n        for r in range(9):\\n            for c in range(9):\\n                if board[r][c] == \\\".\\\":\\n                    for d in map(str, range(1, 10)):\\n                        if is_valid(r, c, d):\\n                            board[r][c] = d\\n                            if solve(): return True\\n                            board[r][c] = \\\".\\\"\\n                    return False\\n        return True\\n    solve()\",\"java\":\"class Solution {\\n    public void solveSudoku(char[][] board) {\\n        solve(board);\\n    }\\n    private boolean solve(char[][] b) {\\n        for (int r = 0; r < 9; r++) {\\n            for (int c = 0; c < 9; c++) {\\n                if (b[r][c] == '.') {\\n                    for (char ch = '1'; ch <= '9'; ch++) {\\n                        if (isValid(b, r, c, ch)) {\\n                            b[r][c] = ch;\\n                            if (solve(b)) return true;\\n                            b[r][c] = '.';\\n                        }\\n                    }\\n                    return false;\\n                }\\n            }\\n        }\\n        return true;\\n    }\\n    private boolean isValid(char[][] b, int r, int c, char ch) {\\n        for (int i = 0; i < 9; i++) {\\n            if (b[r][i] == ch || b[i][c] == ch) return false;\\n            if (b[3 * (r / 3) + i / 3][3 * (c / 3) + i % 3] == ch) return false;\\n        }\\n        return true;\\n    }\\n}\",\"cpp\":\"#include <vector>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    void solveSudoku(vector<vector<char>>& board) {\\n        solve(board);\\n    }\\n    bool solve(vector<vector<char>>& b) {\\n        for (int r = 0; r < 9; r++) {\\n            for (int c = 0; c < 9; c++) {\\n                if (b[r][c] == '.') {\\n                    for (char ch = '1'; ch <= '9'; ch++) {\\n                        if (isValid(b, r, c, ch)) {\\n                            b[r][c] = ch;\\n                            if (solve(b)) return true;\\n                            b[r][c] = '.';\\n                        }\\n                    }\\n                    return false;\\n                }\\n            }\\n        }\\n        return true;\\n    }\\n    bool isValid(const vector<vector<char>>& b, int r, int c, char ch) {\\n        for (int i = 0; i < 9; i++) {\\n            if (b[r][i] == ch || b[i][c] == ch) return false;\\n            if (b[3 * (r / 3) + i / 3][3 * (c / 3) + i % 3] == ch) return false;\\n        }\\n        return true;\\n    }\\n};\"}",
