    "constraints": "[\"The number of nodes in the tree is in the range [2, 10^5].\",\"-10^9 <= Node.val <= 10^9\",\"All Node.val are unique.\",\"p != q and both p and q exist in the tree.\"]",
    "hints": "[\"If root is null or root === p or root === q, return root.\",\"Search left and right subtrees. If both return non-null, root is the LCA.\"]",
    "starterCode": "{\"javascript\":\"function lowestCommonAncestor(root, p, q) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def lowestCommonAncestor(root, p, q):\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function lowestCommonAncestor(root, p, q) {\\n  if (!root || root === p || root === q) return root;\\n  const left = lowestCommonAncestor(root.left, p, q);\\n  const right = lowestCommonAncestor(root.right, p, q);\\n  if (left && right) return root;\\n  return left || right;\\n}\",\"python\":\"def lowestCommonAncestor(root, p, q):\\n    if not root or root == p or root == q: return root\\n    left = lowestCommonAncestor(root.left, p, q)\\n    right = lowestCommonAncestor(root.right, p, q)\\n    if left and right: return root\\n    return left or right\",\"java\":\"class Solution {\\n    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {\\n        if (root == null || root == p || root == q) return root;\\n        TreeNode left = lowestCommonAncestor(root.left, p, q);\\n        TreeNode right = lowestCommonAncestor(root.right, p, q);\\n        if (left != null && right != null) return root;\\n        return left != null ? left : right;\\n    }\\n}\",\"cpp\":\"class Solution {\\npublic:\\n    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {\\n        if (!root || root == p || root == q) return root;\\n        TreeNode* left = lowestCommonAncestor(root->left, p, q);\\n        TreeNode* right = lowestCommonAncestor(root->right, p, q);\\n        if (left && right) return root;\\n        return left ? left : right;\\n    }\\n};\"}",
