    "title": "Binary Tree Maximum Path Sum",
    "slug": "binary-tree-maximum-path-sum",
    "difficulty": "Hard",
    "category": "Trees",
    "description": "A path in a binary tree is a sequence of nodes where each pair of adjacent nodes in the sequence has an edge connecting them. A node can only appear in the sequence at most once. Given the root of a binary tree, return the maximum path sum of any non-empty path.",
    "examples": "[{\"input\":\"root = [1,2,3]\",\"output\":\"6\",\"explanation\":\"Path 2 -> 1 -> 3 has path sum 2 + 1 + 3 = 6.\"},{\"input\":\"root = [-10,9,20,null,null,15,7]\",\"output\":\"42\",\"explanation\":\"Path 15 -> 20 -> 7 has path sum 15 + 20 + 7 = 42.\"}]",
    "constraints": "[\"The number of nodes in the tree is in the range [1, 3 * 10^4].\",\"-1000 <= Node.val <= 1000\"]",
    "hints": "[\"Compute max single branch sum from each node: max(0, dfs(node.left)) and max(0, dfs(node.right)).\",\"Update global max path sum with node.val + leftMax + rightMax.\"]",
    "starterCode": "{\"javascript\":\"function maxPathSum(root) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def maxPathSum(root) -> int:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int maxPathSum(TreeNode root) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int maxPathSum(TreeNode* root) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function maxPathSum(root) {\\n  let maxSum = -Infinity;\\n  function maxGain(node) {\\n    if (!node) return 0;\\n    const leftGain = Math.max(0, maxGain(node.left));\\n    const rightGain = Math.max(0, maxGain(node.right));\\n    maxSum = Math.max(maxSum, node.val + leftGain + rightGain);\\n    return node.val + Math.max(leftGain, rightGain);\\n  }\\n  maxGain(root);\\n  return maxSum;\\n}\",\"python\":\"def maxPathSum(root) -> int:\\n    max_sum = float(\\\"-inf\\\")\\n    def max_gain(node):\\n        nonlocal max_sum\\n        if not node: return 0\\n        left = max(0, max_gain(node.left))\\n        right = max(0, max_gain(node.right))\\n        max_sum = max(max_sum, node.val + left + right)\\n        return node.val + max(left, right)\\n    max_gain(root)\\n    return max_sum\",\"java\":\"class Solution {\\n    private int maxSum = Integer.MIN_VALUE;\\n    public int maxPathSum(TreeNode root) {\\n        maxGain(root);\\n        return maxSum;\\n    }\\n    private int maxGain(TreeNode node) {\\n        if (node == null) return 0;\\n        int left = Math.max(0, maxGain(node.left));\\n        int right = Math.max(0, maxGain(node.right));\\n        maxSum = Math.max(maxSum, node.val + left + right);\\n        return node.val + Math.max(left, right);\\n    }\\n}\",\"cpp\":\"#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\n    int maxSum = -1e9;\\npublic:\\n    int maxPathSum(TreeNode* root) {\\n        maxGain(root);\\n        return maxSum;\\n    }\\n    int maxGain(TreeNode* node) {\\n        if (!node) return 0;\\n        int left = max(0, maxGain(node->left));\\n        int right = max(0, maxGain(node->right));\\n        maxSum = max(maxSum, node->val + left + right);\\n        return node->val + max(left, right);\\n    }\\n};\"}",
