    "hints": "[\"Use preorder DFS with \\\"#\\\" or \\\"null\\\" representing null nodes.\",\"Join values with commas during serialization, and read sequentially during deserialization.\"]",
    "starterCode": "{\"javascript\":\"function serialize(root) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def serialize(self, root) -> str:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public String serialize(TreeNode root) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    string serialize(TreeNode* root) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function serialize(root) {\\n  const res = [];\\n  function dfs(node) {\\n    if (!node) { res.push(\\\"#\\\"); return; }\\n    res.push(node.val);\\n    dfs(node.left);\\n    dfs(node.right);\\n  }\\n  dfs(root);\\n  return res.join(\\\",\\\");\\n}\\n\\nfunction deserialize(data) {\\n  const tokens = data.split(\\\",\\\");\\n  let idx = 0;\\n  function dfs() {\\n    if (tokens[idx] === \\\"#\\\") { idx++; return null; }\\n    const node = { val: parseInt(tokens[idx++]), left: null, right: null };\\n    node.left = dfs();\\n    node.right = dfs();\\n    return node;\\n  }\\n  return dfs();\\n}\",\"python\":\"class Codec:\\n    def serialize(self, root) -> str:\\n        res = []\\n        def dfs(node):\\n            if not node: res.append(\\\"#\\\"); return\\n            res.append(str(node.val))\\n            dfs(node.left); dfs(node.right)\\n        dfs(root)\\n        return \\\",\\\".join(res)\\n    def deserialize(self, data: str):\\n        tokens = data.split(\\\",\\\")\\n        self.idx = 0\\n        def dfs():\\n            if tokens[self.idx] == \\\"#\\\":\\n                self.idx += 1; return None\\n            node = TreeNode(int(tokens[self.idx]))\\n            self.idx += 1\\n            node.left = dfs()\\n            node.right = dfs()\\n            return node\\n        return dfs()\",\"java\":\"public class Codec {\\n    public String serialize(TreeNode root) {\\n        StringBuilder sb = new StringBuilder();\\n        buildString(root, sb);\\n        return sb.toString();\\n    }\\n    private void buildString(TreeNode node, StringBuilder sb) {\\n        if (node == null) { sb.append(\\\"#,\\\"); return; }\\n        sb.append(node.val).append(\\\",\\\");\\n        buildString(node.left, sb); buildString(node.right, sb);\\n    }\\n    public TreeNode deserialize(String data) {\\n        java.util.Deque<String> nodes = new java.util.LinkedList<>();\\n        nodes.addAll(java.util.Arrays.asList(data.split(\\\",\\\")));\\n        return buildTree(nodes);\\n    }\\n    private TreeNode buildTree(java.util.Deque<String> nodes) {\\n        String val = nodes.remove();\\n        if (val.equals(\\\"#\\\")) return null;\\n        TreeNode node = new TreeNode(Integer.parseInt(val));\\n        node.left = buildTree(nodes); node.right = buildTree(nodes);\\n        return node;\\n    }\\n}\",\"cpp\":\"#include <string>\\n#include <sstream>\\nusing namespace std;\\n\\nclass Codec {\\npublic:\\n    string serialize(TreeNode* root) {\\n        if (!root) return \\\"#,\\\";\\n        return to_string(root->val) + \\\",\\\" + serialize(root->left) + serialize(root->right);\\n    }\\n    TreeNode* deserialize(string data) {\\n        stringstream ss(data);\\n        return build(ss);\\n    }\\n    TreeNode* build(stringstream& ss) {\\n        string val;\\n        if (!getline(ss, val, ',') || val == \\\"#\\\") return nullptr;\\n        TreeNode* node = new TreeNode(stoi(val));\\n        node->left = build(ss);\\n        node->right = build(ss);\\n        return node;\\n    }\\n};\"}",
