    "referenceSolution": "{\"javascript\":\"function isValidBST(root, min = -Infinity, max = Infinity) {\\n  if (!root) return true;\\n  if (root.val <= min || root.val >= max) return false;\\n  return isValidBST(root.left, min, root.val) && isValidBST(root.right, root.val, max);\\n}\",\"python\":\"def isValidBST(root, min_val=float(\\\"-inf\\\"), max_val=float(\\\"inf\\\")) -> bool:\\n    if not root: return True\\n    if not (min_val < root.val < max_val): return False\\n    return isValidBST(root.left, min_val, root.val) and isValidBST(root.right, root.val, max_val)\",\"java\":\"class Solution {\\n    public boolean isValidBST(TreeNode root) {\\n        return validate(root, null, null);\\n    }\\n    private boolean validate(TreeNode node, Integer min, Integer max) {\\n        if (node == null) return true;\\n        if ((min != null && node.val <= min) || (max != null && node.val >= max)) return false;\\n        return validate(node.left, min, node.val) && validate(node.right, node.val, max);\\n    }\\n}\",\"cpp\":\"class Solution {\\npublic:\\n    bool isValidBST(TreeNode* root) {\\n        return validate(root, nullptr, nullptr);\\n    }\\n    bool validate(TreeNode* node, TreeNode* minNode, TreeNode* maxNode) {\\n        if (!node) return true;\\n        if ((minNode && node->val <= minNode->val) || (maxNode && node->val >= maxNode->val)) return false;\\n        return validate(node->left, minNode, node) && validate(node->right, node, maxNode);\\n    }\\n};\"}",
