    "referenceSolution": "{\"javascript\":\"function kthSmallest(root, k) {\\n  let count = 0, res = null;\\n  function inorder(node) {\\n    if (!node || res !== null) return;\\n    inorder(node.left);\\n    count++;\\n    if (count === k) { res = node.val; return; }\\n    inorder(node.right);\\n  }\\n  inorder(root);\\n  return res;\\n}\",\"python\":\"def kthSmallest(root, k: int) -> int:\\n    stack = []\\n    curr = root\\n    while curr or stack:\\n        while curr:\\n            stack.append(curr)\\n            curr = curr.left\\n        curr = stack.pop()\\n        k -= 1\\n        if k == 0: return curr.val\\n        curr = curr.right\",\"java\":\"class Solution {\\n    private int count = 0, res = -1;\\n    public int kthSmallest(TreeNode root, int k) {\\n        inorder(root, k);\\n        return res;\\n    }\\n    private void inorder(TreeNode node, int k) {\\n        if (node == null || res != -1) return;\\n        inorder(node.left, k);\\n        if (++count == k) { res = node.val; return; }\\n        inorder(node.right, k);\\n    }\\n}\",\"cpp\":\"#include <stack>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int kthSmallest(TreeNode* root, int k) {\\n        stack<TreeNode*> st;\\n        TreeNode* curr = root;\\n        while (curr || !st.empty()) {\\n            while (curr) { st.push(curr); curr = curr->left; }\\n            curr = st.top(); st.pop();\\n            if (--k == 0) return curr->val;\\n            curr = curr->right;\\n        }\\n        return -1;\\n    }\\n};\"}",
