    "starterCode": "{\"javascript\":\"function deleteNode(root, key) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def deleteNode(root, key: int):\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public TreeNode deleteNode(TreeNode root, int key) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    TreeNode* deleteNode(TreeNode* root, int key) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function deleteNode(root, key) {\\n  if (!root) return null;\\n  if (key < root.val) root.left = deleteNode(root.left, key);\\n  else if (key > root.val) root.right = deleteNode(root.right, key);\\n  else {\\n    if (!root.left) return root.right;\\n    if (!root.right) return root.left;\\n    let succ = root.right;\\n    while (succ.left) succ = succ.left;\\n    root.val = succ.val;\\n    root.right = deleteNode(root.right, succ.val);\\n  }\\n  return root;\\n}\",\"python\":\"def deleteNode(root, key: int):\\n    if not root: return None\\n    if key < root.val: root.left = deleteNode(root.left, key)\\n    elif key > root.val: root.right = deleteNode(root.right, key)\\n    else:\\n        if not root.left: return root.right\\n        if not root.right: return root.left\\n        succ = root.right\\n        while succ.left: succ = succ.left\\n        root.val = succ.val\\n        root.right = deleteNode(root.right, succ.val)\\n    return root\",\"java\":\"class Solution {\\n    public TreeNode deleteNode(TreeNode root, int key) {\\n        if (root == null) return null;\\n        if (key < root.val) root.left = deleteNode(root.left, key);\\n        else if (key > root.val) root.right = deleteNode(root.right, key);\\n        else {\\n            if (root.left == null) return root.right;\\n            if (root.right == null) return root.left;\\n            TreeNode succ = root.right;\\n            while (succ.left != null) succ = succ.left;\\n            root.val = succ.val;\\n            root.right = deleteNode(root.right, succ.val);\\n        }\\n        return root;\\n    }\\n}\",\"cpp\":\"class Solution {\\npublic:\\n    TreeNode* deleteNode(TreeNode* root, int key) {\\n        if (!root) return nullptr;\\n        if (key < root->val) root->left = deleteNode(root->left, key);\\n        else if (key > root->val) root->right = deleteNode(root->right, key);\\n        else {\\n            if (!root->left) return root->right;\\n            if (!root->right) return root->left;\\n            TreeNode* succ = root->right;\\n            while (succ->left) succ = succ->left;\\n            root->val = succ->val;\\n            root->right = deleteNode(root->right, succ->val);\\n        }\\n        return root;\\n    }\\n};\"}",
