    "referenceSolution": "{\"javascript\":\"function kClosest(points, k) {\\n  return points\\n    .sort((a, b) => (a[0]**2 + a[1]**2) - (b[0]**2 + b[1]**2))\\n    .slice(0, k);\\n}\",\"python\":\"def kClosest(points: list[list[int]], k: int) -> list[list[int]]:\\n    points.sort(key=lambda p: p[0]**2 + p[1]**2)\\n    return points[:k]\",\"java\":\"class Solution {\\n    public int[][] kClosest(int[][] points, int k) {\\n        java.util.Arrays.sort(points, (a, b) -> (a[0]*a[0] + a[1]*a[1]) - (b[0]*b[0] + b[1]*b[1]));\\n        return java.util.Arrays.copyOfRange(points, 0, k);\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    vector<vector<int>> kClosest(vector<vector<int>>& points, int k) {\\n        nth_element(points.begin(), points.begin() + k, points.end(), [](const vector<int>& a, const vector<int>& b) {\\n            return (a[0]*a[0] + a[1]*a[1]) < (b[0]*b[0] + b[1]*b[1]);\\n        });\\n        return vector<vector<int>>(points.begin(), points.begin() + k);\\n    }\\n};\"}",
