    "title": "Find Median from Data Stream",
    "slug": "find-median-from-data-stream",
    "difficulty": "Hard",
    "category": "Heap / Priority Queue",
    "description": "The median is the middle value in an ordered integer list. Implement the MedianFinder class supporting addNum(num) and findMedian() in O(log n) and O(1) time respectively.",
    "examples": "[{\"input\":\"[\\\"MedianFinder\\\",\\\"addNum\\\",\\\"addNum\\\",\\\"findMedian\\\",\\\"addNum\\\",\\\"findMedian\\\"]\\n[[],[1],[2],[],[3],[]]\",\"output\":\"[null,null,null,1.5,null,2.0]\",\"explanation\":\"Median from data stream.\"},{\"input\":\"input = []\",\"output\":\"[]\",\"explanation\":\"Boundary empty collection case.\"}]",
    "constraints": "[\"-10^5 <= num <= 10^5\",\"There will be at least one element in the data structure before calling findMedian.\",\"At most 5 * 10^4 calls will be made to addNum and findMedian.\"]",
    "hints": "[\"Maintain two heaps: maxHeap for lower half of numbers, minHeap for upper half.\",\"Balance sizes such that maxHeap has either equal or 1 more element than minHeap.\"]",
    "starterCode": "{\"javascript\":\"class MedianFinder {\\n  constructor() {\\n    // Initialize max-heap and min-heap\\n  }\\n  addNum(num) {\\n    // Add number into data structure\\n  }\\n  findMedian() {\\n    // Return median of all elements so far\\n  }\\n}\",\"python\":\"import heapq\\n\\nclass MedianFinder:\\n    def __init__(self):\\n        pass\\n\\n    def addNum(self, num: int) -> None:\\n        pass\\n\\n    def findMedian(self) -> float:\\n        pass\",\"java\":\"import java.util.PriorityQueue;\\nimport java.util.Collections;\\n\\nclass MedianFinder {\\n    public MedianFinder() {\\n    }\\n    \\n    public void addNum(int num) {\\n    }\\n    \\n    public double findMedian() {\\n        return 0.0;\\n    }\\n}\",\"cpp\":\"#include <queue>\\nusing namespace std;\\n\\nclass MedianFinder {\\npublic:\\n    MedianFinder() {\\n    }\\n    \\n    void addNum(int num) {\\n    }\\n    \\n    double findMedian() {\\n        return 0.0;\\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"class MedianFinder {\\n  constructor() {\\n    this.arr = [];\\n  }\\n  addNum(num) {\\n    let l = 0, r = this.arr.length;\\n    while (l < r) {\\n      const mid = Math.floor((l + r) / 2);\\n      if (this.arr[mid] < num) l = mid + 1;\\n      else r = mid;\\n    }\\n    this.arr.splice(l, 0, num);\\n  }\\n  findMedian() {\\n    const n = this.arr.length;\\n    if (n % 2 === 1) return this.arr[Math.floor(n / 2)];\\n    return (this.arr[n / 2 - 1] + this.arr[n / 2]) / 2;\\n  }\\n}\",\"python\":\"import heapq\\n\\nclass MedianFinder:\\n    def __init__(self):\\n        self.small = [] # max-heap\\n        self.large = [] # min-heap\\n    def addNum(self, num: int) -> None:\\n        heapq.heappush(self.small, -num)\\n        heapq.heappush(self.large, -heapq.heappop(self.small))\\n        if len(self.large) > len(self.small):\\n            heapq.heappush(self.small, -heapq.heappop(self.large))\\n    def findMedian(self) -> float:\\n        if len(self.small) > len(self.large):\\n            return float(-self.small[0])\\n        return (-self.small[0] + self.large[0]) / 2.0\",\"java\":\"class MedianFinder {\\n    private java.util.PriorityQueue<Integer> small = new java.util.PriorityQueue<>((a, b) -> b - a);\\n    private java.util.PriorityQueue<Integer> large = new java.util.PriorityQueue<>();\\n    public void addNum(int num) {\\n        small.offer(num);\\n        large.offer(small.poll());\\n        if (large.size() > small.size()) small.offer(large.poll());\\n    }\\n    public double findMedian() {\\n        if (small.size() > large.size()) return small.peek();\\n        return (small.peek() + large.peek()) / 2.0;\\n    }\\n}\",\"cpp\":\"#include <queue>\\nusing namespace std;\\n\\nclass MedianFinder {\\n    priority_queue<int> small;\\n    priority_queue<int, vector<int>, greater<int>> large;\\npublic:\\n    void addNum(int num) {\\n        small.push(num);\\n        large.push(small.top()); small.pop();\\n        if (large.size() > small.size()) { small.push(large.top()); large.pop(); }\\n    }\\n    double findMedian() {\\n        if (small.size() > large.size()) return small.top();\\n        return (small.top() + large.top()) / 2.0;\\n    }\\n};\"}",
