    "starterCode": "{\"javascript\":\"function canCompleteCircuit(gas, cost) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def canCompleteCircuit(gas: list[int], cost: list[int]) -> int:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int canCompleteCircuit(int[] gas, int[] cost) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int canCompleteCircuit(vector<int>& gas, vector<int>& cost) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function canCompleteCircuit(gas, cost) {\\n  let total = 0, tank = 0, start = 0;\\n  for (let i = 0; i < gas.length; i++) {\\n    const diff = gas[i] - cost[i];\\n    total += diff;\\n    tank += diff;\\n    if (tank < 0) {\\n      start = i + 1;\\n      tank = 0;\\n    }\\n  }\\n  return total >= 0 ? start : -1;\\n}\",\"python\":\"def canCompleteCircuit(gas: list[int], cost: list[int]) -> int:\\n    if sum(gas) < sum(cost): return -1\\n    tank = start = 0\\n    for i in range(len(gas)):\\n        tank += gas[i] - cost[i]\\n        if tank < 0:\\n            start = i + 1\\n            tank = 0\\n    return start\",\"java\":\"class Solution {\\n    public int canCompleteCircuit(int[] gas, int[] cost) {\\n        int total = 0, tank = 0, start = 0;\\n        for (int i = 0; i < gas.length; i++) {\\n            int diff = gas[i] - cost[i];\\n            total += diff; tank += diff;\\n            if (tank < 0) { start = i + 1; tank = 0; }\\n        }\\n        return total >= 0 ? start : -1;\\n    }\\n}\",\"cpp\":\"#include <vector>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int canCompleteCircuit(vector<int>& gas, vector<int>& cost) {\\n        int total = 0, tank = 0, start = 0;\\n        for (size_t i = 0; i < gas.size(); i++) {\\n            int diff = gas[i] - cost[i];\\n            total += diff; tank += diff;\\n            if (tank < 0) { start = i + 1; tank = 0; }\\n        }\\n        return total >= 0 ? start : -1;\\n    }\\n};\"}",
