    "constraints": "[\"n == ratings.length\",\"1 <= n <= 2 * 10^4\",\"0 <= ratings[i] <= 2 * 10^4\"]",
    "hints": "[\"Initialize candies array with 1.\",\"Pass left-to-right: if ratings[i] > ratings[i-1], candies[i] = candies[i-1] + 1.\",\"Pass right-to-left: if ratings[i] > ratings[i+1], candies[i] = max(candies[i], candies[i+1] + 1).\"]",
    "starterCode": "{\"javascript\":\"function candy(ratings) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def candy(ratings: list[int]) -> int:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int candy(int[] ratings) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int candy(vector<int>& ratings) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function candy(ratings) {\\n  const n = ratings.length;\\n  const candies = new Array(n).fill(1);\\n  for (let i = 1; i < n; i++) {\\n    if (ratings[i] > ratings[i - 1]) candies[i] = candies[i - 1] + 1;\\n  }\\n  for (let i = n - 2; i >= 0; i--) {\\n    if (ratings[i] > ratings[i + 1]) candies[i] = Math.max(candies[i], candies[i + 1] + 1);\\n  }\\n  return candies.reduce((a, b) => a + b, 0);\\n}\",\"python\":\"def candy(ratings: list[int]) -> int:\\n    n = len(ratings)\\n    candies = [1] * n\\n    for i in range(1, n):\\n        if ratings[i] > ratings[i - 1]: candies[i] = candies[i - 1] + 1\\n    for i in range(n - 2, -1, -1):\\n        if ratings[i] > ratings[i + 1]: candies[i] = max(candies[i], candies[i + 1] + 1)\\n    return sum(candies)\",\"java\":\"class Solution {\\n    public int candy(int[] ratings) {\\n        int n = ratings.length;\\n        int[] candies = new int[n];\\n        java.util.Arrays.fill(candies, 1);\\n        for (int i = 1; i < n; i++) if (ratings[i] > ratings[i - 1]) candies[i] = candies[i - 1] + 1;\\n        for (int i = n - 2; i >= 0; i--) if (ratings[i] > ratings[i + 1]) candies[i] = Math.max(candies[i], candies[i + 1] + 1);\\n        int sum = 0;\\n        for (int c : candies) sum += c;\\n        return sum;\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <numeric>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int candy(vector<int>& ratings) {\\n        int n = ratings.size();\\n        vector<int> candies(n, 1);\\n        for (int i = 1; i < n; i++) if (ratings[i] > ratings[i - 1]) candies[i] = candies[i - 1] + 1;\\n        for (int i = n - 2; i >= 0; i--) if (ratings[i] > ratings[i + 1]) candies[i] = max(candies[i], candies[i + 1] + 1);\\n        return accumulate(candies.begin(), candies.end(), 0);\\n    }\\n};\"}",
