    "referenceSolution": "{\"javascript\":\"function findOrder(numCourses, prerequisites) {\\n  const inDegree = new Array(numCourses).fill(0);\\n  const adj = Array.from({ length: numCourses }, () => []);\\n  for (const [course, pre] of prerequisites) {\\n    adj[pre].push(course);\\n    inDegree[course]++;\\n  }\\n  const queue = [], order = [];\\n  for (let i = 0; i < numCourses; i++) if (inDegree[i] === 0) queue.push(i);\\n  while (queue.length) {\\n    const node = queue.shift();\\n    order.push(node);\\n    for (const next of adj[node]) {\\n      if (--inDegree[next] === 0) queue.push(next);\\n    }\\n  }\\n  return order.length === numCourses ? order : [];\\n}\",\"python\":\"from collections import deque\\n\\ndef findOrder(numCourses: int, prerequisites: list[list[int]]) -> list[int]:\\n    in_degree = [0] * numCourses\\n    adj = [[] for _ in range(numCourses)]\\n    for course, pre in prerequisites:\\n        adj[pre].append(course)\\n        in_degree[course] += 1\\n    q = deque([i for i in range(numCourses) if in_degree[i] == 0])\\n    order = []\\n    while q:\\n        node = q.popleft()\\n        order.append(node)\\n        for nxt in adj[node]:\\n            in_degree[nxt] -= 1\\n            if in_degree[nxt] == 0: q.append(nxt)\\n    return order if len(order) == numCourses else []\",\"java\":\"class Solution {\\n    public int[] findOrder(int numCourses, int[][] prerequisites) {\\n        int[] inDegree = new int[numCourses];\\n        java.util.List<Integer>[] adj = new java.util.List[numCourses];\\n        for (int i = 0; i < numCourses; i++) adj[i] = new java.util.ArrayList<>();\\n        for (int[] p : prerequisites) {\\n            adj[p[1]].add(p[0]);\\n            inDegree[p[0]]++;\\n        }\\n        java.util.Queue<Integer> q = new java.util.LinkedList<>();\\n        for (int i = 0; i < numCourses; i++) if (inDegree[i] == 0) q.offer(i);\\n        int[] order = new int[numCourses];\\n        int idx = 0;\\n        while (!q.isEmpty()) {\\n            int node = q.poll();\\n            order[idx++] = node;\\n            for (int next : adj[node]) if (--inDegree[next] == 0) q.offer(next);\\n        }\\n        return idx == numCourses ? order : new int[0];\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <queue>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    vector<int> findOrder(int numCourses, vector<vector<int>>& prerequisites) {\\n        vector<int> inDegree(numCourses, 0);\\n        vector<vector<int>> adj(numCourses);\\n        for (auto& p : prerequisites) {\\n            adj[p[1]].push_back(p[0]);\\n            inDegree[p[0]]++;\\n        }\\n        queue<int> q;\\n        for (int i = 0; i < numCourses; i++) if (inDegree[i] == 0) q.push(i);\\n        vector<int> order;\\n        while (!q.empty()) {\\n            int node = q.front(); q.pop();\\n            order.push_back(node);\\n            for (int next : adj[node]) if (--inDegree[next] == 0) q.push(next);\\n        }\\n        return (int)order.size() == numCourses ? order : vector<int>();\\n    }\\n};\"}",
