    "title": "Number of Connected Components in an Undirected Graph",
    "slug": "number-of-connected-components",
    "difficulty": "Medium",
    "category": "Graphs",
    "description": "You have a graph of n nodes. You are given an integer n and an array edges where edges[i] = [ai, bi] indicates that there is an edge between ai and bi in the graph. Return the number of connected components in the graph.",
    "examples": "[{\"input\":\"n = 5, edges = [[0,1],[1,2],[3,4]]\",\"output\":\"2\",\"explanation\":\"Components are {0,1,2} and {3,4}.\"},{\"input\":\"n = 5, edges = [[0,1],[1,2],[2,3],[3,4]]\",\"output\":\"1\",\"explanation\":\"All nodes connected in one component.\"}]",
    "constraints": "[\"1 <= n <= 2000\",\"1 <= edges.length <= 5000\",\"edges[i].length == 2\",\"0 <= ai <= bi < n\"]",
    "hints": "[\"Use Disjoint Set Union (Union-Find) with path compression.\",\"Initialize components count = n, decrement on each successful union.\"]",
    "starterCode": "{\"javascript\":\"function countComponents(n, edges) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def countComponents(n: int, edges: list[list[int]]) -> int:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int countComponents(int n, int[][] edges) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int countComponents(int n, vector<vector<int>>& edges) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function countComponents(n, edges) {\\n  const parent = Array.from({ length: n }, (_, i) => i);\\n  let count = n;\\n  function find(i) {\\n    if (parent[i] === i) return i;\\n    return parent[i] = find(parent[i]);\\n  }\\n  for (const [u, v] of edges) {\\n    const rU = find(u), rV = find(v);\\n    if (rU !== rV) {\\n      parent[rU] = rV;\\n      count--;\\n    }\\n  }\\n  return count;\\n}\",\"python\":\"def countComponents(n: int, edges: list[list[int]]) -> int:\\n    parent = list(range(n))\\n    def find(i):\\n        if parent[i] != i:\\n            parent[i] = find(parent[i])\\n        return parent[i]\\n    count = n\\n    for u, v in edges:\\n        r_u, r_v = find(u), find(v)\\n        if r_u != r_v:\\n            parent[r_u] = r_v\\n            count -= 1\\n    return count\",\"java\":\"class Solution {\\n    public int countComponents(int n, int[][] edges) {\\n        int[] parent = new int[n];\\n        for (int i = 0; i < n; i++) parent[i] = i;\\n        int count = n;\\n        for (int[] e : edges) {\\n            int rU = find(parent, e[0]), rV = find(parent, e[1]);\\n            if (rU != rV) { parent[rU] = rV; count--; }\\n        }\\n        return count;\\n    }\\n    private int find(int[] parent, int i) {\\n        if (parent[i] == i) return i;\\n        return parent[i] = find(parent, parent[i]);\\n    }\\n}\",\"cpp\":\"#include <vector>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int countComponents(int n, vector<vector<int>>& edges) {\\n        vector<int> parent(n);\\n        for (int i = 0; i < n; i++) parent[i] = i;\\n        auto find = [&](auto& self, int i) -> int {\\n            return parent[i] == i ? i : parent[i] = self(self, parent[i]);\\n        };\\n        int count = n;\\n        for (auto& e : edges) {\\n            int rU = find(find, e[0]), rV = find(find, e[1]);\\n            if (rU != rV) { parent[rU] = rV; count--; }\\n        }\\n        return count;\\n    }\\n};\"}",
