    "title": "Alien Dictionary",
    "slug": "alien-dictionary",
    "difficulty": "Hard",
    "category": "Graphs",
    "description": "There is a new alien language that uses the English alphabet. However, the order among letters is unknown to you. You are given a list of strings words from the alien language's dictionary, where the strings are claimed to be sorted lexicographically by the rules of this new language. Return a string of the unique letters in the new alien language sorted in lexicographically increasing order. If the order is invalid, return \"\".",
    "examples": "[{\"input\":\"words = [\\\"wrt\\\",\\\"wrf\\\",\\\"er\\\",\\\"ett\\\",\\\"rftt\\\"]\",\"output\":\"\\\"wertf\\\"\",\"explanation\":\"Topological order of alien characters.\"},{\"input\":\"words = [\\\"z\\\",\\\"x\\\"]\",\"output\":\"\\\"zx\\\"\",\"explanation\":\"z comes before x.\"},{\"input\":\"words = [\\\"z\\\",\\\"x\\\",\\\"z\\\"]\",\"output\":\"\\\"\\\"\",\"explanation\":\"Cycle detected, invalid order.\"}]",
    "constraints": "[\"1 <= words.length <= 100\",\"1 <= words[i].length <= 100\",\"words[i] consists of only lowercase English letters.\"]",
    "hints": "[\"Compare adjacent words to extract directed character precedence edges u -> v.\",\"Check invalid prefix condition: if word2 is prefix of word1 but shorter, return \\\"\\\".\",\"Apply Kahn's topological sort; if output length != number of unique characters, return \\\"\\\".\"]",
    "starterCode": "{\"javascript\":\"function alienOrder(words) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def alienOrder(words: list[str]) -> str:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public String alienOrder(String[] words) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    string alienOrder(vector<string>& words) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function alienOrder(words) {\\n  const adj = new Map(), inDegree = new Map();\\n  for (const w of words) for (const c of w) { adj.set(c, new Set()); inDegree.set(c, 0); }\\n  for (let i = 0; i < words.length - 1; i++) {\\n    const w1 = words[i], w2 = words[i + 1];\\n    if (w1.length > w2.length && w1.startsWith(w2)) return \\\"\\\";\\n    for (let j = 0; j < Math.min(w1.length, w2.length); j++) {\\n      if (w1[j] !== w2[j]) {\\n        if (!adj.get(w1[j]).has(w2[j])) {\\n          adj.get(w1[j]).add(w2[j]);\\n          inDegree.set(w2[j], inDegree.get(w2[j]) + 1);\\n        }\\n        break;\\n      }\\n    }\\n  }\\n  const queue = [];\\n  for (const [c, deg] of inDegree.entries()) if (deg === 0) queue.push(c);\\n  let res = \\\"\\\";\\n  while (queue.length) {\\n    const c = queue.shift();\\n    res += c;\\n    for (const next of adj.get(c)) {\\n      inDegree.set(next, inDegree.get(next) - 1);\\n      if (inDegree.get(next) === 0) queue.push(next);\\n    }\\n  }\\n  return res.length === inDegree.size ? res : \\\"\\\";\\n}\",\"python\":\"from collections import deque, defaultdict\\n\\ndef alienOrder(words: list[str]) -> str:\\n    adj = {c: set() for w in words for c in w}\\n    in_degree = {c: 0 for c in adj}\\n    for i in range(len(words) - 1):\\n        w1, w2 = words[i], words[i + 1]\\n        if len(w1) > len(w2) and w1.startswith(w2): return \\\"\\\"\\n        for c1, c2 in zip(w1, w2):\\n            if c1 != c2:\\n                if c2 not in adj[c1]:\\n                    adj[c1].add(c2)\\n                    in_degree[c2] += 1\\n                break\\n    q = deque([c for c, deg in in_degree.items() if deg == 0])\\n    res = []\\n    while q:\\n        c = q.popleft()\\n        res.append(c)\\n        for nxt in adj[c]:\\n            in_degree[nxt] -= 1\\n            if in_degree[nxt] == 0: q.append(nxt)\\n    return \\\"\\\".join(res) if len(res) == len(in_degree) else \\\"\\\"\",\"java\":\"class Solution {\\n    public String alienOrder(String[] words) {\\n        java.util.Map<Character, java.util.Set<Character>> adj = new java.util.HashMap<>();\\n        java.util.Map<Character, Integer> inDegree = new java.util.HashMap<>();\\n        for (String w : words) for (char c : w.toCharArray()) { adj.putIfAbsent(c, new java.util.HashSet<>()); inDegree.putIfAbsent(c, 0); }\\n        for (int i = 0; i < words.length - 1; i++) {\\n            String w1 = words[i], w2 = words[i + 1];\\n            if (w1.length() > w2.length() && w1.startsWith(w2)) return \\\"\\\";\\n            for (int j = 0; j < Math.min(w1.length(), w2.length()); j++) {\\n                if (w1.charAt(j) != w2.charAt(j)) {\\n                    char c1 = w1.charAt(j), c2 = w2.charAt(j);\\n                    if (!adj.get(c1).contains(c2)) {\\n                        adj.get(c1).add(c2);\\n                        inDegree.put(c2, inDegree.get(c2) + 1);\\n                    }\\n                    break;\\n                }\\n            }\\n        }\\n        java.util.Queue<Character> q = new java.util.LinkedList<>();\\n        for (char c : inDegree.keySet()) if (inDegree.get(c) == 0) q.offer(c);\\n        StringBuilder sb = new StringBuilder();\\n        while (!q.isEmpty()) {\\n            char c = q.poll(); sb.append(c);\\n            for (char next : adj.get(c)) {\\n                inDegree.put(next, inDegree.get(next) - 1);\\n                if (inDegree.get(next) == 0) q.offer(next);\\n            }\\n        }\\n        return sb.length() == inDegree.size() ? sb.toString() : \\\"\\\";\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <unordered_set>\\n#include <queue>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    string alienOrder(vector<string>& words) {\\n        unordered_map<char, unordered_set<char>> adj;\\n        unordered_map<char, int> inDegree;\\n        for (auto& w : words) for (char c : w) { adj[c]; inDegree[c] = 0; }\\n        for (size_t i = 0; i < words.size() - 1; i++) {\\n            string w1 = words[i], w2 = words[i + 1];\\n            if (w1.size() > w2.size() && w1.find(w2) == 0) return \\\"\\\";\\n            for (size_t j = 0; j < min(w1.size(), w2.size()); j++) {\\n                if (w1[j] != w2[j]) {\\n                    if (!adj[w1[j]].count(w2[j])) {\\n                        adj[w1[j]].insert(w2[j]);\\n                        inDegree[w2[j]]++;\\n                    }\\n                    break;\\n                }\\n            }\\n        }\\n        queue<char> q;\\n        for (auto& p : inDegree) if (p.second == 0) q.push(p.first);\\n        string res = \\\"\\\";\\n        while (!q.empty()) {\\n            char c = q.front(); q.pop(); res += c;\\n            for (char next : adj[c]) {\\n                if (--inDegree[next] == 0) q.push(next);\\n            }\\n        }\\n        return res.size() == inDegree.size() ? res : \\\"\\\";\\n    }\\n};\"}",
    "testCases": "[{\"input\":\"[\\\"wrt\\\",\\\"wrf\\\",\\\"er\\\",\\\"ett\\\",\\\"rftt\\\"]\",\"expectedOutput\":\"\\\"wertf\\\"\"},{\"input\":\"[\\\"z\\\",\\\"x\\\"]\",\"expectedOutput\":\"\\\"zx\\\"\"},{\"input\":\"[\\\"z\\\",\\\"x\\\",\\\"z\\\"]\",\"expectedOutput\":\"\\\"\\\"\"}]",
