    "starterCode": "{\"javascript\":\"function ladderLength(beginWord, endWord, wordList) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def ladderLength(beginWord: str, endWord: str, wordList: list[str]) -> int:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int ladderLength(String beginWord, String endWord, java.util.List<String> wordList) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int ladderLength(string beginWord, string endWord, vector<string>& wordList) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function ladderLength(beginWord, endWord, wordList) {\\n  const wordSet = new Set(wordList);\\n  if (!wordSet.has(endWord)) return 0;\\n  const queue = [[beginWord, 1]];\\n  while (queue.length) {\\n    const [word, level] = queue.shift();\\n    if (word === endWord) return level;\\n    for (let i = 0; i < word.length; i++) {\\n      for (let c = 97; c <= 122; c++) {\\n        const next = word.slice(0, i) + String.fromCharCode(c) + word.slice(i + 1);\\n        if (wordSet.has(next)) {\\n          wordSet.delete(next);\\n          queue.push([next, level + 1]);\\n        }\\n      }\\n    }\\n  }\\n  return 0;\\n}\",\"python\":\"from collections import deque\\n\\ndef ladderLength(beginWord: str, endWord: str, wordList: list[str]) -> int:\\n    word_set = set(wordList)\\n    if endWord not in word_set: return 0\\n    q = deque([(beginWord, 1)])\\n    while q:\\n        word, level = q.popleft()\\n        if word == endWord: return level\\n        for i in range(len(word)):\\n            for c in \\\"abcdefghijklmnopqrstuvwxyz\\\":\\n                nxt = word[:i] + c + word[i+1:]\\n                if nxt in word_set:\\n                    word_set.remove(nxt)\\n                    q.append((nxt, level + 1))\\n    return 0\",\"java\":\"class Solution {\\n    public int ladderLength(String beginWord, String endWord, java.util.List<String> wordList) {\\n        java.util.Set<String> wordSet = new java.util.HashSet<>(wordList);\\n        if (!wordSet.contains(endWord)) return 0;\\n        java.util.Queue<String> q = new java.util.LinkedList<>();\\n        q.offer(beginWord);\\n        int level = 1;\\n        while (!q.isEmpty()) {\\n            int sz = q.size();\\n            for (int i = 0; i < sz; i++) {\\n                String word = q.poll();\\n                if (word.equals(endWord)) return level;\\n                char[] chs = word.toCharArray();\\n                for (int j = 0; j < chs.length; j++) {\\n                    char orig = chs[j];\\n                    for (char c = 'a'; c <= 'z'; c++) {\\n                        chs[j] = c;\\n                        String next = String.valueOf(chs);\\n                        if (wordSet.remove(next)) q.offer(next);\\n                    }\\n                    chs[j] = orig;\\n                }\\n            }\\n            level++;\\n        }\\n        return 0;\\n    }\\n}\",\"cpp\":\"#include <string>\\n#include <vector>\\n#include <unordered_set>\\n#include <queue>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int ladderLength(string beginWord, string endWord, vector<string>& wordList) {\\n        unordered_set<string> wordSet(wordList.begin(), wordList.end());\\n        if (!wordSet.count(endWord)) return 0;\\n        queue<pair<string, int>> q;\\n        q.push({beginWord, 1});\\n        while (!q.empty()) {\\n            auto [word, level] = q.front(); q.pop();\\n            if (word == endWord) return level;\\n            for (size_t i = 0; i < word.size(); i++) {\\n                char orig = word[i];\\n                for (char c = 'a'; c <= 'z'; c++) {\\n                    word[i] = c;\\n                    if (wordSet.count(word)) {\\n                        wordSet.erase(word);\\n                        q.push({word, level + 1});\\n                    }\\n                }\\n                word[i] = orig;\\n            }\\n        }\\n        return 0;\\n    }\\n};\"}",
