    "description": "Given an m x n matrix board containing 'X' and 'O', capture all regions that are 4-directionally surrounded by 'X'. A region is captured by flipping all 'O's into 'X's in that surrounded region.",
    "examples": "[{\"input\":\"board = [[\\\"X\\\",\\\"X\\\",\\\"X\\\",\\\"X\\\"],[\\\"X\\\",\\\"O\\\",\\\"O\\\",\\\"X\\\"],[\\\"X\\\",\\\"X\\\",\\\"O\\\",\\\"X\\\"],[\\\"X\\\",\\\"O\\\",\\\"X\\\",\\\"X\\\"]]\",\"output\":\"[[\\\"X\\\",\\\"X\\\",\\\"X\\\",\\\"X\\\"],[\\\"X\\\",\\\"X\\\",\\\"X\\\",\\\"X\\\"],[\\\"X\\\",\\\"X\\\",\\\"X\\\",\\\"X\\\"],[\\\"X\\\",\\\"O\\\",\\\"X\\\",\\\"X\\\"]]\",\"explanation\":\"Internal O region captured, border O preserved.\"},{\"input\":\"board = [[\\\"X\\\"]]\",\"output\":\"[[\\\"X\\\"]]\",\"explanation\":\"Single X.\"}]",
    "constraints": "[\"m == board.length\",\"n == board[i].length\",\"1 <= m, n <= 200\",\"board[i][j] is 'X' or 'O'.\"]",
    "hints": "[\"Any 'O' on the border or connected to the border cannot be captured.\",\"DFS from all border 'O's and mark them as safe ('S').\",\"Flip remaining 'O's to 'X', then restore 'S' back to 'O'.\"]",
    "starterCode": "{\"javascript\":\"function solve(board) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def solve(board: list[list[str]]) -> None:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public void solve(char[][] board) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    void solve(vector<vector<char>>& board) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function solve(board) {\\n  if (!board.length) return;\\n  const m = board.length, n = board[0].length;\\n  function dfs(r, c) {\\n    if (r < 0 || r >= m || c < 0 || c >= n || board[r][c] !== \\\"O\\\") return;\\n    board[r][c] = \\\"S\\\";\\n    dfs(r + 1, c); dfs(r - 1, c); dfs(r, c + 1); dfs(r, c - 1);\\n  }\\n  for (let r = 0; r < m; r++) {\\n    if (board[r][0] === \\\"O\\\") dfs(r, 0);\\n    if (board[r][n - 1] === \\\"O\\\") dfs(r, n - 1);\\n  }\\n  for (let c = 0; c < n; c++) {\\n    if (board[0][c] === \\\"O\\\") dfs(0, c);\\n    if (board[m - 1][c] === \\\"O\\\") dfs(m - 1, c);\\n  }\\n  for (let r = 0; r < m; r++) {\\n    for (let c = 0; c < n; c++) {\\n      if (board[r][c] === \\\"O\\\") board[r][c] = \\\"X\\\";\\n      else if (board[r][c] === \\\"S\\\") board[r][c] = \\\"O\\\";\\n    }\\n  }\\n  return board;\\n}\",\"python\":\"def solve(board: list[list[str]]) -> None:\\n    if not board: return\\n    m, n = len(board), len(board[0])\\n    def dfs(r, c):\\n        if not (0 <= r < m and 0 <= c < n) or board[r][c] != \\\"O\\\": return\\n        board[r][c] = \\\"S\\\"\\n        dfs(r+1, c); dfs(r-1, c); dfs(r, c+1); dfs(r, c-1)\\n    for r in range(m):\\n        if board[r][0] == \\\"O\\\": dfs(r, 0)\\n        if board[r][n-1] == \\\"O\\\": dfs(r, n-1)\\n    for c in range(n):\\n        if board[0][c] == \\\"O\\\": dfs(0, c)\\n        if board[m-1][c] == \\\"O\\\": dfs(m-1, c)\\n    for r in range(m):\\n        for c in range(n):\\n            if board[r][c] == \\\"O\\\": board[r][c] = \\\"X\\\"\\n            elif board[r][c] == \\\"S\\\": board[r][c] = \\\"O\\\"\",\"java\":\"class Solution {\\n    public void solve(char[][] board) {\\n        if (board.length == 0) return;\\n        int m = board.length, n = board[0].length;\\n        for (int r = 0; r < m; r++) {\\n            if (board[r][0] == 'O') dfs(board, r, 0);\\n            if (board[r][n - 1] == 'O') dfs(board, r, n - 1);\\n        }\\n        for (int c = 0; c < n; c++) {\\n            if (board[0][c] == 'O') dfs(board, 0, c);\\n            if (board[m - 1][c] == 'O') dfs(board, m - 1, c);\\n        }\\n        for (int r = 0; r < m; r++) {\\n            for (int c = 0; c < n; c++) {\\n                if (board[r][c] == 'O') board[r][c] = 'X';\\n                else if (board[r][c] == 'S') board[r][c] = 'O';\\n            }\\n        }\\n    }\\n    private void dfs(char[][] b, int r, int c) {\\n        if (r < 0 || r >= b.length || c < 0 || c >= b[0].length || b[r][c] != 'O') return;\\n        b[r][c] = 'S';\\n        dfs(b, r + 1, c); dfs(b, r - 1, c); dfs(b, r, c + 1); dfs(b, r, c - 1);\\n    }\\n}\",\"cpp\":\"#include <vector>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    void solve(vector<vector<char>>& board) {\\n        if (board.empty()) return;\\n        int m = board.size(), n = board[0].size();\\n        auto dfs = [&](auto& self, int r, int c) -> void {\\n            if (r < 0 || r >= m || c < 0 || c >= n || board[r][c] != 'O') return;\\n            board[r][c] = 'S';\\n            self(self, r + 1, c); self(self, r - 1, c); self(self, r, c + 1); self(self, r, c - 1);\\n        };\\n        for (int r = 0; r < m; r++) {\\n            if (board[r][0] == 'O') dfs(dfs, r, 0);\\n            if (board[r][n - 1] == 'O') dfs(dfs, r, n - 1);\\n        }\\n        for (int c = 0; c < n; c++) {\\n            if (board[0][c] == 'O') dfs(dfs, 0, c);\\n            if (board[m - 1][c] == 'O') dfs(dfs, m - 1, c);\\n        }\\n        for (int r = 0; r < m; r++)\\n            for (int c = 0; c < n; c++)\\n                if (board[r][c] == 'O') board[r][c] = 'X';\\n                else if (board[r][c] == 'S') board[r][c] = 'O';\\n    }\\n};\"}",
    "testCases": "[{\"input\":\"[[\\\"X\\\",\\\"X\\\",\\\"X\\\",\\\"X\\\"],[\\\"X\\\",\\\"O\\\",\\\"O\\\",\\\"X\\\"],[\\\"X\\\",\\\"X\\\",\\\"O\\\",\\\"X\\\"],[\\\"X\\\",\\\"O\\\",\\\"X\\\",\\\"X\\\"]]\",\"expectedOutput\":\"[[\\\"X\\\",\\\"X\\\",\\\"X\\\",\\\"X\\\"],[\\\"X\\\",\\\"X\\\",\\\"X\\\",\\\"X\\\"],[\\\"X\\\",\\\"X\\\",\\\"X\\\",\\\"X\\\"],[\\\"X\\\",\\\"O\\\",\\\"X\\\",\\\"X\\\"]]\"},{\"input\":\"Sample input 2\",\"expectedOutput\":\"Expected 2\"},{\"input\":\"Edge case input\",\"expectedOutput\":\"Expected Edge\"}]",
