    "referenceSolution": "{\"javascript\":\"function lengthOfLIS(nums) {\\n  const tails = [];\\n  for (const x of nums) {\\n    let l = 0, r = tails.length;\\n    while (l < r) {\\n      const mid = Math.floor((l + r) / 2);\\n      if (tails[mid] < x) l = mid + 1;\\n      else r = mid;\\n    }\\n    tails[l] = x;\\n  }\\n  return tails.length;\\n}\",\"python\":\"import bisect\\n\\ndef lengthOfLIS(nums: list[int]) -> int:\\n    tails = []\\n    for x in nums:\\n        idx = bisect.bisect_left(tails, x)\\n        if idx == len(tails): tails.append(x)\\n        else: tails[idx] = x\\n    return len(tails)\",\"java\":\"class Solution {\\n    public int lengthOfLIS(int[] nums) {\\n        int[] tails = new int[nums.length];\\n        int size = 0;\\n        for (int x : nums) {\\n            int l = 0, r = size;\\n            while (l < r) {\\n                int mid = (l + r) / 2;\\n                if (tails[mid] < x) l = mid + 1;\\n                else r = mid;\\n            }\\n            tails[l] = x;\\n            if (l == size) size++;\\n        }\\n        return size;\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int lengthOfLIS(vector<int>& nums) {\\n        vector<int> tails;\\n        for (int x : nums) {\\n            auto it = lower_bound(tails.begin(), tails.end(), x);\\n            if (it == tails.end()) tails.push_back(x);\\n            else *it = x;\\n        }\\n        return tails.size();\\n    }\\n};\"}",
