    "starterCode": "{\"javascript\":\"function findWords(board, words) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def findWords(board: list[list[str]], words: list[str]) -> list[str]:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public void solve() {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    vector<string> findWords(vector<vector<char>>& board, vector<string>& words) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function findWords(board, words) {\\n  const root = {};\\n  for (const w of words) {\\n    let node = root;\\n    for (const c of w) {\\n      if (!node[c]) node[c] = {};\\n      node = node[c];\\n    }\\n    node.word = w;\\n  }\\n  const res = new Set(), m = board.length, n = board[0].length;\\n  function dfs(r, c, node) {\\n    if (r < 0 || r >= m || c < 0 || c >= n || !node[board[r][c]]) return;\\n    const ch = board[r][c];\\n    const nextNode = node[ch];\\n    if (nextNode.word) res.add(nextNode.word);\\n    board[r][c] = \\\"#\\\";\\n    dfs(r + 1, c, nextNode);\\n    dfs(r - 1, c, nextNode);\\n    dfs(r, c + 1, nextNode);\\n    dfs(r, c - 1, nextNode);\\n    board[r][c] = ch;\\n  }\\n  for (let r = 0; r < m; r++) {\\n    for (let c = 0; c < n; c++) dfs(r, c, root);\\n  }\\n  return Array.from(res);\\n}\",\"python\":\"def findWords(board: list[list[str]], words: list[str]) -> list[str]:\\n    root = {}\\n    for w in words:\\n        node = root\\n        for c in w: node = node.setdefault(c, {})\\n        node[\\\"$\\\"] = w\\n    res, m, n = set(), len(board), len(board[0])\\n    def dfs(r, c, node):\\n        if not (0 <= r < m and 0 <= c < n) or board[r][c] not in node: return\\n        ch = board[r][c]\\n        next_node = node[ch]\\n        if \\\"$\\\" in next_node: res.add(next_node[\\\"$\\\"])\\n        board[r][c] = \\\"#\\\"\\n        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:\\n            dfs(r+dr, c+dc, next_node)\\n        board[r][c] = ch\\n    for r in range(m):\\n        for c in range(n): dfs(r, c, root)\\n    return list(res)\",\"java\":\"class Solution {\\n    class Node { Node[] next = new Node[26]; String word; }\\n    public java.util.List<String> findWords(char[][] board, String[] words) {\\n        Node root = new Node();\\n        for (String w : words) {\\n            Node node = root;\\n            for (char c : w.toCharArray()) {\\n                if (node.next[c - 'a'] == null) node.next[c - 'a'] = new Node();\\n                node = node.next[c - 'a'];\\n            }\\n            node.word = w;\\n        }\\n        java.util.List<String> res = new java.util.ArrayList<>();\\n        for (int r = 0; r < board.length; r++) {\\n            for (int c = 0; c < board[0].length; c++) dfs(board, r, c, root, res);\\n        }\\n        return res;\\n    }\\n    private void dfs(char[][] b, int r, int c, Node node, java.util.List<String> res) {\\n        if (r < 0 || r >= b.length || c < 0 || c >= b[0].length || b[r][c] == '#' || node.next[b[r][c] - 'a'] == null) return;\\n        char ch = b[r][c];\\n        Node next = node.next[ch - 'a'];\\n        if (next.word != null) { res.add(next.word); next.word = null; }\\n        b[r][c] = '#';\\n        dfs(b, r + 1, c, next, res); dfs(b, r - 1, c, next, res);\\n        dfs(b, r, c + 1, next, res); dfs(b, r, c - 1, next, res);\\n        b[r][c] = ch;\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_set>\\nusing namespace std;\\n\\nclass Solution {\\n    struct Node { Node* next[26] = {}; string word = \\\"\\\"; };\\n    Node* root = new Node();\\npublic:\\n    vector<string> findWords(vector<vector<char>>& board, vector<string>& words) {\\n        for (const string& w : words) {\\n            Node* node = root;\\n            for (char c : w) {\\n                if (!node->next[c - 'a']) node->next[c - 'a'] = new Node();\\n                node = node->next[c - 'a'];\\n            }\\n            node->word = w;\\n        }\\n        unordered_set<string> res;\\n        for (size_t r = 0; r < board.size(); r++)\\n            for (size_t c = 0; c < board[0].size(); c++) dfs(board, r, c, root, res);\\n        return vector<string>(res.begin(), res.end());\\n    }\\n    void dfs(vector<vector<char>>& b, int r, int c, Node* node, unordered_set<string>& res) {\\n        if (r < 0 || r >= (int)b.size() || c < 0 || c >= (int)b[0].size() || b[r][c] == '#' || !node->next[b[r][c] - 'a']) return;\\n        char ch = b[r][c];\\n        Node* next = node->next[ch - 'a'];\\n        if (!next->word.empty()) res.insert(next->word);\\n        b[r][c] = '#';\\n        dfs(b, r + 1, c, next, res); dfs(b, r - 1, c, next, res);\\n        dfs(b, r, c + 1, next, res); dfs(b, r, c - 1, next, res);\\n        b[r][c] = ch;\\n    }\\n};\"}",
