    "title": "Insert Interval",
    "slug": "insert-interval",
    "difficulty": "Medium",
    "category": "Intervals",
    "description": "You are given an array of non-overlapping intervals intervals where intervals[i] = [starti, endi] sorted in ascending order by starti. You are also given an interval newInterval = [start, end]. Insert newInterval into intervals such that intervals is still sorted and non-overlapping.",
    "examples": "[{\"input\":\"intervals = [[1,3],[6,9]], newInterval = [2,5]\",\"output\":\"[[1,5],[6,9]]\",\"explanation\":\"Intervals merged with [2,5].\"},{\"input\":\"intervals = [[1,2],[3,5],[6,7],[8,10],[12,16]], newInterval = [4,8]\",\"output\":\"[[1,2],[3,10],[12,16]]\",\"explanation\":\"Merged overlapping range [3,10].\"}]",
    "constraints": "[\"0 <= intervals.length <= 10^4\",\"intervals[i].length == 2\",\"0 <= starti <= endi <= 10^5\",\"intervals is sorted by starti in ascending order.\"]",
    "hints": "[\"Append all intervals that end before newInterval begins.\",\"Merge all overlapping intervals with newInterval: newInterval = [min(start), max(end)].\",\"Append all remaining intervals that begin after newInterval ends.\"]",
    "starterCode": "{\"javascript\":\"function insert(intervals, newInterval) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def insert(intervals: list[list[int]], newInterval: list[int]) -> list[list[int]]:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int[][] insert(int[][] intervals, int[] newInterval) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    vector<vector<int>> insert(vector<vector<int>>& intervals, vector<int>& newInterval) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function insert(intervals, newInterval) {\\n  const res = [];\\n  let i = 0, n = intervals.length;\\n  while (i < n && intervals[i][1] < newInterval[0]) res.push(intervals[i++]);\\n  while (i < n && intervals[i][0] <= newInterval[1]) {\\n    newInterval[0] = Math.min(newInterval[0], intervals[i][0]);\\n    newInterval[1] = Math.max(newInterval[1], intervals[i][1]);\\n    i++;\\n  }\\n  res.push(newInterval);\\n  while (i < n) res.push(intervals[i++]);\\n  return res;\\n}\",\"python\":\"def insert(intervals: list[list[int]], newInterval: list[int]) -> list[list[int]]:\\n    res = []\\n    i, n = 0, len(intervals)\\n    while i < n and intervals[i][1] < newInterval[0]:\\n        res.append(intervals[i]); i += 1\\n    while i < n and intervals[i][0] <= newInterval[1]:\\n        newInterval = [min(newInterval[0], intervals[i][0]), max(newInterval[1], intervals[i][1])]\\n        i += 1\\n    res.append(newInterval)\\n    while i < n: res.append(intervals[i]); i += 1\\n    return res\",\"java\":\"class Solution {\\n    public int[][] insert(int[][] intervals, int[] newInterval) {\\n        java.util.List<int[]> res = new java.util.ArrayList<>();\\n        int i = 0, n = intervals.length;\\n        while (i < n && intervals[i][1] < newInterval[0]) res.add(intervals[i++]);\\n        while (i < n && intervals[i][0] <= newInterval[1]) {\\n            newInterval[0] = Math.min(newInterval[0], intervals[i][0]);\\n            newInterval[1] = Math.max(newInterval[1], intervals[i][1]);\\n            i++;\\n        }\\n        res.add(newInterval);\\n        while (i < n) res.add(intervals[i++]);\\n        return res.toArray(new int[res.size()][]);\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    vector<vector<int>> insert(vector<vector<int>>& intervals, vector<int>& newInterval) {\\n        vector<vector<int>> res;\\n        size_t i = 0, n = intervals.size();\\n        while (i < n && intervals[i][1] < newInterval[0]) res.push_back(intervals[i++]);\\n        while (i < n && intervals[i][0] <= newInterval[1]) {\\n            newInterval[0] = min(newInterval[0], intervals[i][0]);\\n            newInterval[1] = max(newInterval[1], intervals[i][1]);\\n            i++;\\n        }\\n        res.push_back(newInterval);\\n        while (i < n) res.push_back(intervals[i++]);\\n        return res;\\n    }\\n};\"}",
    "testCases": "[{\"input\":\"[[1,3],[6,9]], [2,5]\",\"expectedOutput\":\"[[1,5],[6,9]]\"},{\"input\":\"[[1,2],[3,5],[6,7],[8,10],[12,16]], [4,8]\",\"expectedOutput\":\"[[1,2],[3,10],[12,16]]\"},{\"input\":\"Edge case input\",\"expectedOutput\":\"Expected Edge\"}]",
    "relatedSkillName": "Data Structures & Algorithms (DSA)",
    "contentReady": true
