    "starterCode": "{\"javascript\":\"function rotate(matrix) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def rotate(matrix: list[list[int]]) -> None:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public void rotate(int[][] matrix) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    void rotate(vector<vector<int>>& matrix) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function rotate(matrix) {\\n  const n = matrix.length;\\n  for (let i = 0; i < n; i++) {\\n    for (let j = i + 1; j < n; j++) {\\n      const temp = matrix[i][j];\\n      matrix[i][j] = matrix[j][i];\\n      matrix[j][i] = temp;\\n    }\\n  }\\n  for (let i = 0; i < n; i++) {\\n    matrix[i].reverse();\\n  }\\n  return matrix;\\n}\",\"python\":\"def rotate(matrix: list[list[int]]) -> None:\\n    n = len(matrix)\\n    for i in range(n):\\n        for j in range(i + 1, n):\\n            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]\\n    for row in matrix: row.reverse()\",\"java\":\"class Solution {\\n    public void rotate(int[][] matrix) {\\n        int n = matrix.length;\\n        for (int i = 0; i < n; i++) {\\n            for (int j = i + 1; j < n; j++) {\\n                int t = matrix[i][j]; matrix[i][j] = matrix[j][i]; matrix[j][i] = t;\\n            }\\n        }\\n        for (int i = 0; i < n; i++) {\\n            for (int j = 0; j < n / 2; j++) {\\n                int t = matrix[i][j]; matrix[i][j] = matrix[i][n - 1 - j]; matrix[i][n - 1 - j] = t;\\n            }\\n        }\\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    void rotate(vector<vector<int>>& matrix) {\\n        int n = matrix.size();\\n        for (int i = 0; i < n; i++) {\\n            for (int j = i + 1; j < n; j++) swap(matrix[i][j], matrix[j][i]);\\n        }\\n        for (int i = 0; i < n; i++) reverse(matrix[i].begin(), matrix[i].end());\\n    }\\n};\"}",
