    "starterCode": "{\"javascript\":\"function countPrimes(n) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def countPrimes(n: int) -> int:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public int countPrimes(int n) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int countPrimes(int n) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function countPrimes(n) {\\n  if (n <= 2) return 0;\\n  const isPrime = new Uint8Array(n).fill(1);\\n  isPrime[0] = isPrime[1] = 0;\\n  for (let p = 2; p * p < n; p++) {\\n    if (isPrime[p]) {\\n      for (let i = p * p; i < n; i += p) isPrime[i] = 0;\\n    }\\n  }\\n  return isPrime.reduce((acc, val) => acc + val, 0);\\n}\",\"python\":\"def countPrimes(n: int) -> int:\\n    if n <= 2: return 0\\n    is_prime = bytearray([1]) * n\\n    is_prime[0] = is_prime[1] = 0\\n    for p in range(2, int(n**0.5) + 1):\\n        if is_prime[p]:\\n            is_prime[p*p:n:p] = bytearray([0]) * len(is_prime[p*p:n:p])\\n    return sum(is_prime)\",\"java\":\"class Solution {\\n    public int countPrimes(int n) {\\n        if (n <= 2) return 0;\\n        boolean[] isPrime = new boolean[n];\\n        java.util.Arrays.fill(isPrime, true);\\n        for (int p = 2; p * p < n; p++) {\\n            if (isPrime[p]) {\\n                for (int i = p * p; i < n; i += p) isPrime[i] = false;\\n            }\\n        }\\n        int count = 0;\\n        for (int i = 2; i < n; i++) if (isPrime[i]) count++;\\n        return count;\\n    }\\n}\",\"cpp\":\"#include <vector>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    int countPrimes(int n) {\\n        if (n <= 2) return 0;\\n        vector<bool> isPrime(n, true);\\n        for (int p = 2; p * p < n; p++) {\\n            if (isPrime[p]) {\\n                for (int i = p * p; i < n; i += p) isPrime[i] = false;\\n            }\\n        }\\n        int count = 0;\\n        for (int i = 2; i < n; i++) if (isPrime[i]) count++;\\n        return count;\\n    }\\n};\"}",
