    "starterCode": "{\"javascript\":\"function multiply(num1, num2) {\\n  // Write your solution here\\n  \\n}\",\"python\":\"def multiply(num1: str, num2: str) -> str:\\n    # Write your solution here\\n    pass\",\"java\":\"class Solution {\\n    public String multiply(String num1, String num2) {\\n        // Write your solution here\\n        \\n    }\\n}\",\"cpp\":\"#include <vector>\\n#include <string>\\n#include <unordered_map>\\n#include <algorithm>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    string multiply(string num1, string num2) {\\n        // Write your solution here\\n        \\n    }\\n};\"}",
    "referenceSolution": "{\"javascript\":\"function multiply(num1, num2) {\\n  if (num1 === \\\"0\\\" || num2 === \\\"0\\\") return \\\"0\\\";\\n  const m = num1.length, n = num2.length;\\n  const pos = new Array(m + n).fill(0);\\n  for (let i = m - 1; i >= 0; i--) {\\n    for (let j = n - 1; j >= 0; j--) {\\n      const mul = parseInt(num1[i]) * parseInt(num2[j]);\\n      const p1 = i + j, p2 = i + j + 1;\\n      const sum = mul + pos[p2];\\n      pos[p2] = sum % 10;\\n      pos[p1] += Math.floor(sum / 10);\\n    }\\n  }\\n  while (pos.length > 1 && pos[0] === 0) pos.shift();\\n  return pos.join(\\\"\\\");\\n}\",\"python\":\"def multiply(num1: str, num2: str) -> str:\\n    if num1 == \\\"0\\\" or num2 == \\\"0\\\": return \\\"0\\\"\\n    m, n = len(num1), len(num2)\\n    pos = [0] * (m + n)\\n    for i in range(m - 1, -1, -1):\\n        for j in range(n - 1, -1, -1):\\n            mul = int(num1[i]) * int(num2[j])\\n            p1, p2 = i + j, i + j + 1\\n            s = mul + pos[p2]\\n            pos[p2] = s % 10\\n            pos[p1] += s // 10\\n    start = 0\\n    while start < len(pos) - 1 and pos[start] == 0: start += 1\\n    return \\\"\\\".join(map(str, pos[start:]))\",\"java\":\"class Solution {\\n    public String multiply(String num1, String num2) {\\n        if (num1.equals(\\\"0\\\") || num2.equals(\\\"0\\\")) return \\\"0\\\";\\n        int m = num1.length(), n = num2.length;\\n        int[] pos = new int[m + n];\\n        for (int i = m - 1; i >= 0; i--) {\\n            for (int j = n - 1; j >= 0; j--) {\\n                int mul = (num1.charAt(i) - '0') * (num2.charAt(j) - '0');\\n                int p1 = i + j, p2 = i + j + 1;\\n                int sum = mul + pos[p2];\\n                pos[p2] = sum % 10;\\n                pos[p1] += sum / 10;\\n            }\\n        }\\n        StringBuilder sb = new StringBuilder();\\n        for (int p : pos) if (!(sb.length() == 0 && p == 0)) sb.append(p);\\n        return sb.length() == 0 ? \\\"0\\\" : sb.toString();\\n    }\\n}\",\"cpp\":\"#include <string>\\n#include <vector>\\nusing namespace std;\\n\\nclass Solution {\\npublic:\\n    string multiply(string num1, string num2) {\\n        if (num1 == \\\"0\\\" || num2 == \\\"0\\\") return \\\"0\\\";\\n        int m = num1.size(), n = num2.size();\\n        vector<int> pos(m + n, 0);\\n        for (int i = m - 1; i >= 0; i--) {\\n            for (int j = n - 1; j >= 0; j--) {\\n                int mul = (num1[i] - '0') * (num2[j] - '0');\\n                int p1 = i + j, p2 = i + j + 1;\\n                int sum = mul + pos[p2];\\n                pos[p2] = sum % 10;\\n                pos[p1] += sum / 10;\\n            }\\n        }\\n        string res = \\\"\\\";\\n        for (int p : pos) if (!(res.empty() && p == 0)) res += to_string(p);\\n        return res.empty() ? \\\"0\\\" : res;\\n    }\\n};\"}",
